insert into public.concept_nodes (id, kind, title, purpose, status, source_refs, maintainer) values
  ('core-en-module-01', 'trunk', 'Meaning → Clause', 'Từ ý định và sự việc đến mệnh đề có cấu trúc để tự sinh câu.', 'published', ARRAY['claude-owner-paste:english-2026-08-25', 'english-core-sources:v1']::text[], 'hiep'),
  ('core-en-module-02', 'branch', 'Verb Architecture', 'Verb hữu hạn, verb từ vựng và hệ trợ động từ be/do/have/modal.', 'published', ARRAY['claude-owner-paste:english-2026-08-25', 'english-core-sources:v1']::text[], 'hiep'),
  ('core-en-module-03', 'branch', 'Negation & Questions', 'Cách mệnh đề đổi thành phủ định và câu hỏi bằng do-support, be hoặc modal.', 'published', ARRAY['claude-owner-paste:english-2026-08-25', 'english-core-sources:v1']::text[], 'hiep'),
  ('core-en-module-04', 'branch', 'Time, Aspect & Modality', 'Tách tense, aspect, modality và futurity constructions thành các cơ chế có thể suy ra.', 'published', ARRAY['claude-owner-paste:english-2026-08-25', 'english-core-sources:v1']::text[], 'hiep'),
  ('core-en-module-05', 'branch', 'Noun & Reference', 'Cấu trúc noun phrase, countability, determiner và cách người nói xác định đối tượng.', 'published', ARRAY['claude-owner-paste:english-2026-08-25', 'english-core-sources:v1']::text[], 'hiep'),
  ('core-en-module-06', 'branch', 'Expanding the Clause', 'Bổ sung complement, modifier, coordination, subordination và relative clause.', 'published', ARRAY['claude-owner-paste:english-2026-08-25', 'english-core-sources:v1']::text[], 'hiep'),
  ('core-en-module-07', 'branch', 'Information Flow', 'Tổ chức given/new information, focus, active/passive và discourse context.', 'published', ARRAY['claude-owner-paste:english-2026-08-25', 'english-core-sources:v1']::text[], 'hiep'),
  ('core-en-module-08', 'branch', 'Sound & Listening', 'Nhận diện âm, prominence, reduction, linking, segmentation và intonation.', 'published', ARRAY['claude-owner-paste:english-2026-08-25', 'english-core-sources:v1']::text[], 'hiep'),
  ('core-en-module-09', 'branch', 'Lexicon as a Network', 'Từ tần suất cao, word family, collocation và continuum của phrasal verb.', 'published', ARRAY['claude-owner-paste:english-2026-08-25', 'english-core-sources:v1']::text[], 'hiep'),
  ('core-en-module-10', 'leaf', 'Integration & Production', 'Tích hợp gọi ý, biến đổi, nghe, nói và chuyển giao sang tình huống mới.', 'published', ARRAY['claude-owner-paste:english-2026-08-25', 'english-core-sources:v1']::text[], 'hiep')
