insert into public.cards (id, node_id, card_type, prompt, model_answer, explanation, misconception, transfer_prompt, transfer_answer, glossary_refs, prerequisite_node_ids, source_refs, status, author, reviewer) values
  ('core-en-01', 'core-en-module-01', 'core_recall', 'Khi muốn nói một điều bằng tiếng Anh, vì sao cần biến ý định thành một mệnh đề thay vì ghép các từ dịch rời? Hãy minh hoạ bằng ‘The child opened the door.’', 'Mệnh đề tổ chức một sự việc quanh các vai trò như subject và predicate: trong câu này the child là subject, opened là verb trung tâm và the door là object.', 'Cấu trúc vai trò cho người nghe biết ai làm gì với cái gì; từ đó có thể sinh nhiều câu mới thay vì nhớ một chuỗi dịch cố định.', 'Chỉ cần đủ từ vựng là câu tự đúng, không cần cấu trúc vai trò.', 'Từ ý ‘một người bạn gửi email’, tạo một mệnh đề và chỉ ra các vai trò.', 'My friend sent an email. My friend là subject, sent là finite lexical verb, và an email là object.', ARRAY['clause', 'subject', 'predicate', 'object']::text[], ARRAY[]::text[], ARRAY['claude-owner-paste:english-2026-08-25', 'english-core-sources:v1', 'core-synthesis:english-generative-core-v1', 'english-core-transfer-answers-v1']::text[], 'published', 'codex', 'hiep'),
  ('core-en-02', 'core-en-module-01', 'mechanism', 'Trong ‘Maya seems tired’, vì sao seems vẫn là verb dù không chỉ một hành động nhìn thấy được?', 'Verb có thể làm trung tâm của sự kiện, hành động hoặc trạng thái; seems liên kết Maya với trạng thái tired.', 'Nhận diện verb theo công việc trong mệnh đề giúp ta không đồng nhất verb với chuyển động vật lý.', 'Một từ chỉ là verb khi nó mô tả hành động có thể quan sát.', 'Viết một câu dùng ‘know’ hoặc ‘belong’ và giải thích trạng thái mà verb đó tổ chức.', 'This bag belongs to Hoàng. Belongs không mô tả hành động nhìn thấy được; nó tổ chức trạng thái sở hữu/quan hệ giữa this bag và Hoàng.', ARRAY['clause', 'lexical-verb', 'predicate']::text[], ARRAY['core-en-module-01']::text[], ARRAY['claude-owner-paste:english-2026-08-25', 'english-core-sources:v1', 'core-synthesis:english-generative-core-v1', 'english-core-transfer-answers-v1']::text[], 'published', 'codex', 'hiep'),
  ('core-en-03', 'core-en-module-01', 'mechanism', 'Trong ‘The dog chased the cat’, trật tự từ giúp người nghe suy ra ai làm gì như thế nào?', 'Khuôn S-V-O mặc định đặt the dog trước verb nên là subject, the cat sau verb nên là object; vị trí là tín hiệu vai trò mạnh.', 'Tiếng Anh dựa nhiều vào word order và function words để đóng gói quan hệ trong câu.', 'Chỉ cần dịch từng từ sang tiếng Anh là quan hệ vai trò vẫn giữ nguyên.', 'Đổi vị trí hai noun trong câu và mô tả nghĩa mới hoặc sự bất tự nhiên tạo ra.', 'Đổi thành ‘The cat chased the dog’ thì vai trò cũng đổi: the cat trở thành subject/agent và the dog thành object/patient. ‘Chased the dog the cat’ bất tự nhiên vì phá khuôn tín hiệu vai trò mặc định.', ARRAY['clause', 'subject', 'object']::text[], ARRAY['core-en-module-01']::text[], ARRAY['claude-owner-paste:english-2026-08-25', 'english-core-sources:v1', 'core-synthesis:english-generative-core-v1', 'english-core-transfer-answers-v1']::text[], 'published', 'codex', 'hiep'),
  ('core-en-04', 'core-en-module-01', 'contrast', 'Phân biệt ‘the quiet room’ với ‘The room is quiet’: điều gì khiến một cái là noun phrase còn cái kia là mệnh đề?', 'The quiet room chỉ gọi tên một đối tượng; The room is quiet có subject, verb is và predicate mô tả một trạng thái.', 'Phân biệt cụm danh từ với mệnh đề ngăn việc coi mọi nhóm từ là câu.', 'Một cụm có adjective là đã nói được một sự việc hoàn chỉnh.', 'Biến ‘a very old bridge’ thành một câu có thể đúng hoặc sai về cây cầu.', '‘The bridge is very old.’ A very old bridge chỉ gọi tên một đối tượng; câu mới có subject the bridge và finite verb is nên có thể được đánh giá đúng hoặc sai.', ARRAY['noun-phrase', 'clause', 'predicate']::text[], ARRAY['core-en-module-01']::text[], ARRAY['claude-owner-paste:english-2026-08-25', 'english-core-sources:v1', 'core-synthesis:english-generative-core-v1', 'english-core-transfer-answers-v1']::text[], 'published', 'codex', 'hiep'),
  ('core-en-05', 'core-en-module-01', 'boundary', 'Vì sao S-V-O là khuôn mặc định hữu ích nhưng không phải luật tuyệt đối của mọi câu tiếng Anh?', 'Nhiều câu dùng S-V-O, nhưng câu hỏi, bị động, copular clause và cấu trúc không có object thay đổi bề mặt; nguyên lý là nhận diện vai trò, không ép mọi câu vào một khuôn.', 'Một mô hình sinh tốt phải chỉ rõ phạm vi áp dụng và những cơ chế khác có thể tái tổ chức câu.', 'Mọi câu đúng đều phải có đủ subject, verb và object theo đúng thứ tự.', 'So sánh ‘The window broke’ và ‘The window was broken’; câu nào có object và vì sao?', '‘The window broke’ không có object: the window là subject của một sự việc xảy ra. ‘The window was broken’ cũng không có object ở bề mặt; the window là subject/patient trong passive, còn tác nhân có thể thêm bằng by-phrase.', ARRAY['clause', 'subject', 'object', 'auxiliary']::text[], ARRAY['core-en-module-01']::text[], ARRAY['claude-owner-paste:english-2026-08-25', 'english-core-sources:v1', 'core-synthesis:english-generative-core-v1', 'english-core-transfer-answers-v1']::text[], 'published', 'codex', 'hiep'),
  ('core-en-06', 'core-en-module-01', 'application', 'Hãy phân tích cấu trúc của câu mới ‘The small robot moved the box carefully’ mà không dịch từng từ.', 'The small robot là subject noun phrase, moved là verb, the box là object noun phrase, carefully là adjunct chỉ cách thức.', 'Bắt đầu từ trung tâm mệnh đề rồi mở rộng ra các thành phần giúp suy luận nhanh hơn từ bản dịch tuyến tính.', 'Carefully là object vì nó đứng sau verb.', 'Tạo một câu khác có subject, verb, object và adjunct chỉ thời gian.', '‘My sister finished the report yesterday.’ My sister là subject, finished là verb, the report là object, yesterday là adjunct chỉ thời gian.', ARRAY['clause', 'subject', 'object', 'adjunct', 'noun-phrase']::text[], ARRAY['core-en-module-01']::text[], ARRAY['claude-owner-paste:english-2026-08-25', 'english-core-sources:v1', 'core-synthesis:english-generative-core-v1', 'english-core-transfer-answers-v1']::text[], 'published', 'codex', 'hiep'),
  ('core-en-07', 'core-en-module-01', 'production', 'Tự nói hoặc viết một câu tiếng Anh về việc bạn vừa làm; hãy chỉ ra subject, finite verb và phần bổ nghĩa.', 'Một câu hợp lệ phải có mệnh đề rõ; ví dụ ‘I finished my notes’ có I là subject, finished là finite verb và my notes là object.', 'Tự tạo câu kiểm tra việc nguyên lý đã chuyển thành thao tác, không chỉ nhận ra đáp án có sẵn.', 'Chỉ cần nói một noun hoặc một verb riêng lẻ là đã thực hành tạo câu.', 'Giữ cùng ý nhưng đổi subject và thời điểm để tạo câu thứ hai.', 'Từ ‘I finished my notes’ có thể đổi thành ‘Hoàng will finish his notes tomorrow.’ Subject đổi thành Hoàng; finite carrier là will; thời điểm chuyển từ việc đã xong sang tương lai dự kiến.', ARRAY['clause', 'subject', 'finite-verb', 'modifier']::text[], ARRAY['core-en-module-01']::text[], ARRAY['claude-owner-paste:english-2026-08-25', 'english-core-sources:v1', 'core-synthesis:english-generative-core-v1', 'english-core-transfer-answers-v1']::text[], 'published', 'codex', 'hiep'),
  ('core-en-08', 'core-en-module-01', 'production', 'Hãy giải thích bằng lời của bạn vì sao ‘The cat sleeps’ là câu, còn ‘under the table’ chỉ là một mảnh; sau đó tạo một câu mới từ mảnh đó.', 'The cat sleeps có subject và predicate với finite verb; under the table chỉ là prepositional phrase. Có thể tạo ‘The cat sleeps under the table.’', 'Giải thích rồi chuyển mảnh vào cấu trúc mới kiểm tra cả nhận diện lẫn thao tác xây câu.', 'Cụm giới từ tự nó luôn là một câu vì có nghĩa rõ.', 'Lấy một prepositional phrase khác và gắn nó vào một mệnh đề mới mà không làm mất trung tâm câu.', 'Với prepositional phrase ‘after dinner’, ta có ‘We reviewed the lesson after dinner.’ Trung tâm mệnh đề vẫn là We reviewed the lesson; after dinner chỉ thêm hoàn cảnh thời gian.', ARRAY['clause', 'subject', 'predicate', 'object']::text[], ARRAY['core-en-module-01']::text[], ARRAY['claude-owner-paste:english-2026-08-25', 'english-core-sources:v1', 'core-synthesis:english-generative-core-v1', 'english-core-transfer-answers-v1']::text[], 'published', 'codex', 'hiep'),
  ('core-en-09', 'core-en-module-02', 'core_recall', 'Finite verb khác lexical verb ở điểm nào? Hãy dùng ‘She walks’ để minh hoạ.', 'Finite verb là thành phần mang tense/agreement trong mệnh đề; trong ‘She walks’, walks vừa là lexical verb vừa là finite form.', 'Tách công việc ngữ pháp của finite khỏi nghĩa từ vựng giúp hiểu vì sao auxiliary có thể mang dấu hiệu còn verb chính trở về base form.', 'Finite verb nghĩa là verb diễn tả hành động hữu hạn về thời lượng.', 'Chỉ ra finite verb trong ‘She has walked home’ và phần lexical meaning nằm ở đâu.', 'Trong ‘She has walked home’, has là finite auxiliary mang present form/agreement; walked là non-finite past participle và mang lexical meaning ‘đi bộ’.', ARRAY['finite-verb', 'lexical-verb', 'auxiliary', 'clause']::text[], ARRAY['core-en-module-01']::text[], ARRAY['claude-owner-paste:english-2026-08-25', 'english-core-sources:v1', 'core-synthesis:english-generative-core-v1', 'english-core-transfer-answers-v1']::text[], 'published', 'codex', 'hiep'),
  ('core-en-10', 'core-en-module-02', 'mechanism', 'Ba từ ‘be’, ‘do’ và ‘have’ có thể làm những công việc ngữ pháp nào trong ‘They are working’, ‘Do they work?’ và ‘They have finished’?', 'Be hỗ trợ progressive, do hỗ trợ câu hỏi khi không có auxiliary khác, have hỗ trợ perfect; mỗi từ cũng có thể là lexical verb mang nghĩa riêng.', 'Học auxiliary theo chức năng tạo ra nhiều cấu trúc từ một vài cơ chế chung.', 'Be, do, have luôn là ba dạng bất quy tắc phải học thuộc mà không có hệ thống.', 'Phân biệt have trong ‘They have finished’ và ‘They have a car’.', 'Trong ‘They have finished’, have là auxiliary mở perfect và finished là participle. Trong ‘They have a car’, have là lexical verb mang nghĩa sở hữu và tự làm finite verb.', ARRAY['auxiliary', 'lexical-verb', 'finite-verb']::text[], ARRAY['core-en-module-02']::text[], ARRAY['claude-owner-paste:english-2026-08-25', 'english-core-sources:v1', 'core-synthesis:english-generative-core-v1', 'english-core-transfer-answers-v1']::text[], 'published', 'codex', 'hiep'),
  ('core-en-11', 'core-en-module-02', 'mechanism', 'Trong ‘She walks’ và ‘She is walking’, thành phần nào mang thông tin hữu hạn và phần còn lại làm công việc gì?', 'Ở ‘She walks’, walks là finite lexical verb; ở ‘She is walking’, is là finite auxiliary còn walking là non-finite -ing form.', 'Một mệnh đề thường cần một finite carrier; auxiliary có thể nhận gánh nặng ngữ pháp để verb lexical biểu thị aspect.', 'Mọi verb xuất hiện trong câu đều cùng lúc mang tense.', 'Phân tích ‘She has been working’ theo finite carrier và các form còn lại.', 'Trong ‘She has been working’, has là finite carrier; been là past participle của be trong perfect; working là -ing form mang lexical event. Chuỗi auxiliary phân lớp thông tin quanh nghĩa work.', ARRAY['finite-verb', 'non-finite-verb', 'clause']::text[], ARRAY['core-en-module-02']::text[], ARRAY['claude-owner-paste:english-2026-08-25', 'english-core-sources:v1', 'core-synthesis:english-generative-core-v1', 'english-core-transfer-answers-v1']::text[], 'published', 'codex', 'hiep'),
  ('core-en-12', 'core-en-module-02', 'contrast', 'Phân biệt ‘I have a car’ với ‘I have finished’: vì sao cùng một từ nhưng một câu không phải perfect?', 'Trong ‘I have a car’, have là lexical verb nghĩa sở hữu; trong ‘I have finished’, have là auxiliary mở cấu trúc perfect với past participle finished.', 'Hình thức bề mặt chưa đủ; phải xét vai trò của từ trong cấu trúc và thành phần theo sau.', 'Hễ thấy have trước một noun hoặc verb là perfect.', 'Tạo hai câu mới với ‘have’, một lexical và một auxiliary, rồi giải thích dấu hiệu nhận biết.', 'Lexical: ‘I have two brothers’—have nghĩa là có. Auxiliary: ‘I have completed the task’—have đứng trước participle completed để tạo perfect; dấu hiệu là sau nó có past participle.', ARRAY['auxiliary', 'aspect', 'modality', 'finite-verb']::text[], ARRAY['core-en-module-02']::text[], ARRAY['claude-owner-paste:english-2026-08-25', 'english-core-sources:v1', 'core-synthesis:english-generative-core-v1', 'english-core-transfer-answers-v1']::text[], 'published', 'codex', 'hiep'),
  ('core-en-13', 'core-en-module-02', 'boundary', 'Vì sao công thức ‘thêm -s cho ngôi thứ ba số ít’ không mô tả đầy đủ mọi verb hiện tại đơn?', 'Đó là quy tắc productive cho nhiều lexical verb, nhưng be và have có dạng riêng; cần nhận diện lexicalized irregular forms thay vì áp dụng -s máy móc.', 'Gốc là cơ chế agreement, còn bề mặt của một số verb là dữ liệu ngoại lệ cần tích lũy.', 'Biết quy tắc -s là chia đúng mọi verb.', 'So sánh go→goes với have→has và nói rõ đâu là spelling pattern, đâu là irregular form.', 'Go→goes theo spelling pattern thêm -es sau -o cho third-person singular. Have→has là một irregular form phải học như lexicalized exception, không suy đơn thuần bằng cách thêm -s.', ARRAY['lexical-verb', 'auxiliary', 'clause']::text[], ARRAY['core-en-module-02']::text[], ARRAY['claude-owner-paste:english-2026-08-25', 'english-core-sources:v1', 'core-synthesis:english-generative-core-v1', 'english-core-transfer-answers-v1']::text[], 'published', 'codex', 'hiep'),
  ('core-en-14', 'core-en-module-02', 'application', 'Hãy biến ‘She works here’ thành câu hỏi và phủ định, giải thích verb nào mang tense trong mỗi câu.', '‘Does she work here?’ và ‘She does not work here.’ Do/does là finite auxiliary; work trở về base form.', 'Do-support cho thấy tense/agreement chuyển sang auxiliary khi cấu trúc cần đảo hoặc phủ định.', 'Giữ ‘works’ sau does vì subject vẫn là she.', 'Áp dụng cùng cơ chế với ‘He watches TV’.', '‘Does he watch TV?’ và ‘He does not watch TV.’ Does mang present agreement/finite information; watches trở về base form watch sau auxiliary.', ARRAY['lexical-verb', 'valency', 'complement']::text[], ARRAY['core-en-module-02']::text[], ARRAY['claude-owner-paste:english-2026-08-25', 'english-core-sources:v1', 'core-synthesis:english-generative-core-v1', 'english-core-transfer-answers-v1']::text[], 'published', 'codex', 'hiep'),
  ('core-en-15', 'core-en-module-02', 'production', 'Tự tạo một cặp câu dùng cùng lexical verb: một câu có auxiliary và một câu không có auxiliary; giải thích vai trò của finite carrier.', 'Ví dụ ‘They have left’ có have là auxiliary và left mang lexical meaning; ‘They leave early’ có leave vừa lexical vừa finite.', 'Tự dựng cặp đối chiếu buộc người học vận dụng kiến trúc verb thay vì lặp định nghĩa.', 'Một lexical verb không bao giờ có thể là finite verb.', 'Đổi cặp trên sang một verb khác và giữ nguyên sự khác nhau về kiến trúc.', '‘They have written the report’ có have là finite auxiliary và written mang lexical meaning. ‘They write reports weekly’ có write vừa mang lexical meaning vừa là finite verb.', ARRAY['finite-verb', 'tense', 'clause']::text[], ARRAY['core-en-module-02']::text[], ARRAY['claude-owner-paste:english-2026-08-25', 'english-core-sources:v1', 'core-synthesis:english-generative-core-v1', 'english-core-transfer-answers-v1']::text[], 'published', 'codex', 'hiep'),
  ('core-en-16', 'core-en-module-02', 'production', 'Giải thích cho một người mới học vì sao học ‘be/do/have’ theo công việc sẽ sinh được nhiều câu hơn học từng bảng chia riêng.', 'Vì mỗi auxiliary mang một loại thông tin và tái xuất hiện trong nhiều tense/aspect/câu hỏi/phủ định; biết chức năng giúp suy ra câu mới, rồi mới học các dạng bất quy tắc.', 'Đây là cách biến một nhóm nhỏ cơ chế thành đòn bẩy cho nhiều cành sử dụng.', 'Học thuộc càng nhiều bảng động từ càng chứng minh đã hiểu hệ thống.', 'Chọn một auxiliary và nêu ba cấu trúc khác nhau mà nó có thể tham gia.', 'Với be: ‘She is ready’ dùng be như copular verb; ‘She is working’ dùng be cho progressive; ‘The door was opened’ dùng be cho passive. Cùng một auxiliary job giúp sinh nhiều cấu trúc.', ARRAY['finite-verb', 'lexical-verb', 'auxiliary', 'predicate']::text[], ARRAY['core-en-module-02']::text[], ARRAY['claude-owner-paste:english-2026-08-25', 'english-core-sources:v1', 'core-synthesis:english-generative-core-v1', 'english-core-transfer-answers-v1']::text[], 'published', 'codex', 'hiep'),
  ('core-en-17', 'core-en-module-03', 'core_recall', 'Câu hỏi yes/no tiếng Anh thường làm thay đổi trật tự mệnh đề và finite verb như thế nào? Hãy dùng ‘You are ready.’', 'Finite be đi trước subject: ‘Are you ready?’; cấu trúc với be không cần thêm do.', 'Inversion biến cấu trúc trần thuật thành câu hỏi bằng cách đưa finite be hoặc một auxiliary lên trước subject.', 'Chỉ cần thêm dấu hỏi hoặc do vào đầu mọi câu.', 'Đổi ‘They can swim’ thành câu hỏi và chỉ ra carrier.', '‘Can they swim?’ Carrier là modal can; nó đi trước subject they. Không thêm do vì can đã là finite auxiliary.', ARRAY['finite-verb', 'auxiliary', 'clause']::text[], ARRAY['core-en-module-02']::text[], ARRAY['claude-owner-paste:english-2026-08-25', 'english-core-sources:v1', 'core-synthesis:english-generative-core-v1', 'english-core-transfer-answers-v1']::text[], 'published', 'codex', 'hiep'),
  ('core-en-18', 'core-en-module-03', 'mechanism', 'Vì sao ‘She likes tea’ trở thành ‘Does she like tea?’ thay vì ‘Does she likes tea?’', 'Does là finite auxiliary mang present agreement; lexical verb sau auxiliary dùng base form like.', 'Một mệnh đề chỉ cần một finite carrier trong cấu trúc này; do-support chuyển gánh nặng hình thái khỏi lexical verb.', '-s phải xuất hiện trên mọi verb đi với subject she.', 'Giải thích ‘Did she like tea?’ theo cùng cơ chế nhưng với past.', '‘Did she like tea?’ Did mang past finite information; lexical verb dùng base form like. Vì vậy không dùng ‘did ... liked’.', ARRAY['auxiliary', 'lexical-verb', 'modality', 'clause']::text[], ARRAY['core-en-module-03']::text[], ARRAY['claude-owner-paste:english-2026-08-25', 'english-core-sources:v1', 'core-synthesis:english-generative-core-v1', 'english-core-transfer-answers-v1']::text[], 'published', 'codex', 'hiep'),
  ('core-en-19', 'core-en-module-03', 'mechanism', 'Trong ‘I do not understand’, do đang mang ý nghĩa ‘làm’ hay đang làm công việc ngữ pháp?', 'Do là auxiliary hỗ trợ negation; lexical verb understand mang nghĩa chính, nên do ở đây không có nghĩa ‘làm’.', 'Một hình thức có thể là lexical verb hoặc grammatical auxiliary; vai trò được xác định bởi cấu trúc.', 'Do trong mọi câu đều có nghĩa là làm.', 'So sánh ‘I do my homework’ với ‘I do not understand’.', '‘I do my homework’ dùng do như lexical verb nghĩa ‘làm’. ‘I do not understand’ dùng do như finite auxiliary cho negation; understand mới mang nghĩa chính.', ARRAY['clause', 'auxiliary', 'subject']::text[], ARRAY['core-en-module-03']::text[], ARRAY['claude-owner-paste:english-2026-08-25', 'english-core-sources:v1', 'core-synthesis:english-generative-core-v1', 'english-core-transfer-answers-v1']::text[], 'published', 'codex', 'hiep'),
  ('core-en-20', 'core-en-module-03', 'contrast', 'Phân biệt cách phủ định ‘She is ready’, ‘She has left’ và ‘She works here’: vì sao không dùng cùng một công thức?', 'Finite be và auxiliary have nhận not trực tiếp; với lexical work không có auxiliary phù hợp nên dùng does not.', 'Chọn cơ chế phủ định bắt đầu từ việc tìm finite be hoặc auxiliary đã có; chỉ dùng do-support khi cấu trúc cần một carrier.', 'Mọi câu phủ định đều phải dùng do not.', 'Viết phủ định cho ‘They can help’ và ‘They help’ rồi giải thích khác nhau.', '‘They cannot help’ đặt not trực tiếp sau modal can. ‘They do not help’ phải thêm do vì help là lexical verb và chưa có auxiliary để mang negation.', ARRAY['clause', 'auxiliary', 'subject']::text[], ARRAY['core-en-module-03']::text[], ARRAY['claude-owner-paste:english-2026-08-25', 'english-core-sources:v1', 'core-synthesis:english-generative-core-v1', 'english-core-transfer-answers-v1']::text[], 'published', 'codex', 'hiep'),
  ('core-en-21', 'core-en-module-03', 'boundary', 'Vì sao không thể áp dụng do-support giống nhau cho mọi câu hỏi, đặc biệt với ‘Who broke the window?’', 'Wh-question hỏi chính subject có thể không cần đảo hoặc do-support; cấu trúc phụ thuộc thành phần được hỏi và auxiliary đang có.', 'Quy tắc question formation có điều kiện; không nên biến một mẫu phổ biến thành công thức tuyệt đối.', 'Mọi câu hỏi đều phải bắt đầu bằng do/does/did.', 'So sánh ‘Who called you?’ với ‘Who did you call?’ và xác định object/subject được hỏi.', '‘Who called you?’ hỏi subject: who đứng ở vị trí người gọi nên không cần do. ‘Who did you call?’ hỏi object: you vẫn là subject, did là finite auxiliary, call trở về base form.', ARRAY['auxiliary', 'lexical-verb', 'finite-verb']::text[], ARRAY['core-en-module-03']::text[], ARRAY['claude-owner-paste:english-2026-08-25', 'english-core-sources:v1', 'core-synthesis:english-generative-core-v1', 'english-core-transfer-answers-v1']::text[], 'published', 'codex', 'hiep'),
  ('core-en-22', 'core-en-module-03', 'application', 'Hãy biến ‘They have finished the work’ thành câu hỏi và phủ định mà không làm mất cấu trúc perfect.', '‘Have they finished the work?’ và ‘They have not finished the work.’ Have là auxiliary finite nên đảo hoặc nhận not; finished giữ nguyên.', 'Khi auxiliary đã có, không thêm do; thao tác giữ nguyên phần lexical/aspectual phía sau.', 'Dùng ‘Do they have finished...?’ vì nghĩ mọi câu hỏi cần do.', 'Làm tương tự với ‘She has been waiting’.', '‘Has she been waiting?’ và ‘She has not been waiting.’ Has là finite auxiliary nên được đảo hoặc nhận not; been waiting giữ cấu trúc perfect progressive.', ARRAY['auxiliary', 'clause', 'modality']::text[], ARRAY['core-en-module-03']::text[], ARRAY['claude-owner-paste:english-2026-08-25', 'english-core-sources:v1', 'core-synthesis:english-generative-core-v1', 'english-core-transfer-answers-v1']::text[], 'published', 'codex', 'hiep'),
  ('core-en-23', 'core-en-module-03', 'production', 'Tự tạo một câu khẳng định, câu hỏi và câu phủ định về lịch học của bạn; nói rõ auxiliary nào đang mang finite information.', 'Ví dụ ‘I study at night’, ‘Do I study at night?’, ‘I do not study at night’; do/does là carrier trong hai câu biến đổi.', 'Ba dạng liên tiếp kiểm tra cơ chế biến đổi mệnh đề và khả năng tự kiểm lỗi.', 'Chỉ cần đổi dấu câu là tạo được câu hỏi tiếng Anh.', 'Lặp lại với một câu dùng be hoặc modal để thấy khi nào do biến mất.', 'Với be: ‘I am free tonight’, ‘Am I free tonight?’, ‘I am not free tonight.’ Am tự mang finite information nên đảo/nhận not trực tiếp và do biến mất.', ARRAY['clause', 'subject', 'object']::text[], ARRAY['core-en-module-03']::text[], ARRAY['claude-owner-paste:english-2026-08-25', 'english-core-sources:v1', 'core-synthesis:english-generative-core-v1', 'english-core-transfer-answers-v1']::text[], 'published', 'codex', 'hiep'),
  ('core-en-24', 'core-en-module-03', 'production', 'Giải thích bằng ví dụ mới vì sao câu hỏi tiếng Anh là thao tác trên cấu trúc chứ không phải chỉ đặt ‘what/why’ ở đầu.', 'Câu hỏi phải xác định thành phần cần lấy thông tin và tổ chức auxiliary/inversion phù hợp; ví dụ ‘Where did she go?’ dùng did + base go.', 'Tự giải thích cơ chế giúp phân biệt wh-word, vị trí được hỏi và finite carrier.', 'Thêm wh-word vào đầu bất kỳ câu nào là đủ.', 'Tạo một wh-question hỏi subject và một câu hỏi hỏi object, rồi chỉ ra khác biệt.', 'Hỏi subject: ‘Who sent the message?’—who là người gửi, không cần do. Hỏi object: ‘What did Hoàng send?’—Hoàng là subject, what là object, did mang finite information.', ARRAY['clause', 'auxiliary', 'finite-verb']::text[], ARRAY['core-en-module-03']::text[], ARRAY['claude-owner-paste:english-2026-08-25', 'english-core-sources:v1', 'core-synthesis:english-generative-core-v1', 'english-core-transfer-answers-v1']::text[], 'published', 'codex', 'hiep'),
  ('core-en-25', 'core-en-module-04', 'core_recall', 'Tense, aspect và modality trả lời ba câu hỏi khác nhau nào? Hãy dùng một ví dụ ngắn.', 'Tense định vị hoặc nhìn sự việc qua present/past form; aspect chọn cách nhìn bên trong hay nhìn lại sự việc; modality biểu thị khả năng, nghĩa vụ hoặc thái độ. Ví dụ ‘She may be working’ có may là modality và be working là progressive aspect.', 'Tách ba hệ thống giúp người học chọn cấu trúc theo ý nghĩa thay vì coi mọi tổ hợp là một ‘thì’ riêng phải học thuộc.', 'Mọi chuỗi auxiliary + verb đều là một tense độc lập.', 'Phân tích ‘They must have left’ thành tense, aspect và modality.', 'Trong ‘They must have left’, must biểu thị modality/nghĩa vụ hoặc suy luận mạnh; have + left tạo perfect aspect; must là finite carrier nhưng không đánh dấu present/past time trực tiếp, nên thời điểm cụ thể phải dựa vào context.', ARRAY['tense', 'aspect', 'clause']::text[], ARRAY['core-en-module-02']::text[], ARRAY['claude-owner-paste:english-2026-08-25', 'english-core-sources:v1', 'core-synthesis:english-generative-core-v1', 'english-core-transfer-answers-v1']::text[], 'published', 'codex', 'hiep'),
  ('core-en-26', 'core-en-module-04', 'mechanism', 'Vì sao present form và past form không đơn giản tương ứng với ‘bây giờ’ và ‘đã qua’ trong mọi câu?', 'Chúng là hình thức ngữ pháp có nhiều cách dùng: present có thể nói thói quen hoặc lịch; past có thể kể quá khứ nhưng cũng biểu thị độ xa, giả định hoặc lịch sự.', 'Hình thức tense góp phần định vị, nhưng nghĩa thời gian cuối cùng còn phụ thuộc loại sự việc, ngữ cảnh và cấu trúc khác.', 'Thấy past form là sự việc chắc chắn đã xảy ra trong quá khứ.', 'Giải thích past form trong ‘If I knew the answer, I would tell you.’', 'Trong ‘If I knew the answer, I would tell you’, knew có past form nhưng biểu thị remoteness/giả định trái hoặc xa thực tế hiện tại, không khẳng định một sự biết trong quá khứ.', ARRAY['tense', 'aspect']::text[], ARRAY['core-en-module-04']::text[], ARRAY['claude-owner-paste:english-2026-08-25', 'english-core-sources:v1', 'core-synthesis:english-generative-core-v1', 'english-core-transfer-answers-v1']::text[], 'published', 'codex', 'hiep'),
  ('core-en-27', 'core-en-module-04', 'mechanism', 'Progressive và perfect thay đổi góc nhìn sự việc như thế nào trong ‘She worked’, ‘She was working’ và ‘She had worked’?', 'Worked kể sự việc bằng past; was working nhìn vào diễn tiến quanh một mốc quá khứ; had worked nhìn sự việc như đã có trước một mốc quá khứ khác.', 'Aspect không đổi bản thân sự việc; nó chọn cách người nói đóng khung quan hệ bên trong hoặc quan hệ với một mốc tham chiếu.', 'Progressive luôn nghĩa là hành động kéo dài, perfect luôn nghĩa là hành động vừa kết thúc.', 'Chọn một ngữ cảnh trong đó ‘I read’, ‘I was reading’ và ‘I had read’ tạo ba cách nhìn khác nhau.', '‘I read the report yesterday’ kể sự việc quá khứ; ‘I was reading it when you called’ nhìn vào diễn tiến tại mốc cuộc gọi; ‘I had read it before the meeting began’ nhìn việc đọc như đã hoàn tất trước một mốc quá khứ khác.', ARRAY['tense', 'aspect']::text[], ARRAY['core-en-module-04']::text[], ARRAY['claude-owner-paste:english-2026-08-25', 'english-core-sources:v1', 'core-synthesis:english-generative-core-v1', 'english-core-transfer-answers-v1']::text[], 'published', 'codex', 'hiep'),
  ('core-en-28', 'core-en-module-04', 'contrast', 'So sánh ‘I will call’, ‘I am going to call’ và ‘I am calling her tonight’: chúng khác nhau ở loại tín hiệu nào?', 'Will thường trình bày dự đoán hoặc quyết định theo ngữ cảnh; be going to thường gắn với ý định hay bằng chứng hiện tại; present progressive có thể diễn đạt một sắp xếp đã được tổ chức.', 'Tiếng Anh biểu đạt tương lai bằng nhiều construction và modal meaning, không chỉ bằng một đuôi future tense duy nhất.', 'Ba câu hoàn toàn đồng nghĩa và có thể thay nhau ở mọi ngữ cảnh.', 'Bạn đã đặt lịch với bác sĩ vào thứ Sáu: chọn construction tự nhiên và nói vì sao.', '‘I am seeing the doctor on Friday.’ Present progressive tự nhiên vì đây là một arrangement đã được đặt lịch, không chỉ là dự đoán hay ý định mơ hồ.', ARRAY['modality', 'tense', 'clause']::text[], ARRAY['core-en-module-04']::text[], ARRAY['claude-owner-paste:english-2026-08-25', 'english-core-sources:v1', 'core-synthesis:english-generative-core-v1', 'english-core-transfer-answers-v1']::text[], 'published', 'codex', 'hiep'),
  ('core-en-29', 'core-en-module-04', 'boundary', 'Vì sao bảng ‘3 thời điểm × 4 dạng = 12 thì’ hữu ích để ôn mẫu nhưng nguy hiểm nếu coi là bản chất tiếng Anh?', 'Bảng giúp nhìn một số tổ hợp form, nhưng trộn tense với aspect và cách diễn đạt tương lai; nó không dự đoán đầy đủ nghĩa theo ngữ cảnh, modality hay các cách dùng phi thời gian của past form.', 'Mô hình học tập tốt phải cho phép suy luận và chỉ rõ chỗ mô hình dừng lại.', 'Bỏ hoàn toàn bảng mẫu thì mới hiểu ngôn ngữ theo nguyên lý.', 'Lấy một ô trong bảng và mô tả riêng tense form, aspect và ý nghĩa do ngữ cảnh tạo ra.', 'Ví dụ ô ‘present perfect’: tense form nằm ở present have/has; perfect aspect là have + past participle; câu ‘She has left’ có thể nghĩa là việc rời đi đã xảy ra và kết quả còn liên quan ở hiện tại, nhưng ngữ cảnh quyết định mốc và relevance cụ thể.', ARRAY['tense', 'modality', 'aspect']::text[], ARRAY['core-en-module-04']::text[], ARRAY['claude-owner-paste:english-2026-08-25', 'english-core-sources:v1', 'core-synthesis:english-generative-core-v1', 'english-core-transfer-answers-v1']::text[], 'published', 'codex', 'hiep'),
  ('core-en-30', 'core-en-module-04', 'application', 'Phân tích ‘She may have been waiting for an hour’: mỗi thành phần đóng góp điều gì?', 'May biểu thị khả năng; have + participle tạo perfect; been + waiting tạo progressive; toàn chuỗi nhìn một diễn tiến đã kéo tới mốc tham chiếu với độ chắc chắn hạn chế.', 'Đọc auxiliary từ trái sang phải theo tầng chức năng giúp xử lý tổ hợp dài mà không cần đặt tên một ‘thì’ mới.', 'Mọi auxiliary trong chuỗi cùng mang một nghĩa thời gian giống nhau.', 'Phân tích ‘They must have forgotten’ theo cùng cách.', 'Trong ‘They must have forgotten’, must biểu thị suy luận mạnh; have + forgotten tạo perfect; forgotten là past participle mang event meaning. Câu nhìn việc quên như đã xảy ra trước mốc hiện tại với độ chắc chắn cao của người nói.', ARRAY['tense', 'aspect', 'clause']::text[], ARRAY['core-en-module-02', 'core-en-module-04']::text[], ARRAY['claude-owner-paste:english-2026-08-25', 'english-core-sources:v1', 'core-synthesis:english-generative-core-v1', 'english-core-transfer-answers-v1']::text[], 'published', 'codex', 'hiep'),
  ('core-en-31', 'core-en-module-04', 'production', 'Tạo ba câu về cùng việc ‘học tiếng Anh’: một thói quen, một diễn tiến ngay lúc nói và một kinh nghiệm tính đến hiện tại.', 'Ví dụ: ‘I study English every day’, ‘I am studying English now’, và ‘I have studied English for two years’; mỗi câu chọn form/aspect theo góc nhìn cần nói.', 'Giữ cùng nội dung từ vựng nhưng đổi góc nhìn buộc người học nối form với ý định giao tiếp.', 'Chỉ cần thay trạng từ thời gian, verb form nào cũng được.', 'Đổi cả ba câu sang một subject khác và kiểm tra finite carrier.', '‘She studies English every day’, ‘She is studying English now’, ‘She has studied English for two years.’ Finite carriers lần lượt là studies, is và has; subject mới làm studies mang -s.', ARRAY['auxiliary', 'tense', 'aspect', 'modality']::text[], ARRAY['core-en-module-04']::text[], ARRAY['claude-owner-paste:english-2026-08-25', 'english-core-sources:v1', 'core-synthesis:english-generative-core-v1', 'english-core-transfer-answers-v1']::text[], 'published', 'codex', 'hiep'),
  ('core-en-32', 'core-en-module-04', 'production', 'Hãy giải thích cho người mới vì sao ‘Could you open the window?’ dùng past-form could nhưng không kể chuyện quá khứ.', 'Could ở đây tạo độ xa về thái độ, khiến lời yêu cầu bớt trực diện; past morphology có thể biểu thị remoteness chứ không chỉ past time.', 'Một nguyên lý về remoteness giải thích được cả giả định và một số cách nói lịch sự.', 'Could luôn là quá khứ của can và chỉ dùng cho khả năng đã mất.', 'Tạo một cặp yêu cầu với can/could và mô tả khác biệt về sắc thái, không gán một câu là luôn lịch sự hơn trong mọi ngữ cảnh.', '‘Can you help me?’ trực tiếp hơn trong nhiều ngữ cảnh; ‘Could you help me?’ tạo độ xa và thường làm request mềm hơn. Quan hệ, giọng nói và tình huống vẫn có thể đổi sắc thái nên không có công thức lịch sự tuyệt đối.', ARRAY['tense', 'aspect', 'modality', 'clause']::text[], ARRAY['core-en-module-04']::text[], ARRAY['claude-owner-paste:english-2026-08-25', 'english-core-sources:v1', 'core-synthesis:english-generative-core-v1', 'english-core-transfer-answers-v1']::text[], 'published', 'codex', 'hiep'),
  ('core-en-33', 'core-en-module-05', 'core_recall', 'Noun phrase làm công việc gì ngoài việc ‘chứa một danh từ’? Hãy phân tích ‘those two old books on the shelf’.', 'Noun phrase giúp người nói dựng và xác định một đối tượng; books là head, those/two giới hạn reference, old mô tả, và on the shelf thu hẹp đối tượng.', 'Học noun phrase như một hệ thống reference giải thích vì sao người nghe biết ta đang nói tới cái nào, bao nhiêu và thuộc loại gì.', 'Chỉ noun head quyết định toàn bộ nghĩa; các từ xung quanh là trang trí.', 'Tạo một noun phrase có head ‘student’ và ít nhất hai lớp thông tin để người nghe nhận đúng người.', '‘Those two diligent students in the front row’: students là head; those và two giúp xác định; diligent mô tả; in the front row thu hẹp nhóm để người nghe nhận đúng người.', ARRAY['noun-phrase', 'modifier', 'reference']::text[], ARRAY['core-en-module-01']::text[], ARRAY['claude-owner-paste:english-2026-08-25', 'english-core-sources:v1', 'core-synthesis:english-generative-core-v1', 'english-core-transfer-answers-v1']::text[], 'published', 'codex', 'hiep'),
  ('core-en-34', 'core-en-module-05', 'mechanism', 'Head và dependent trong noun phrase phân chia công việc thế nào trong ‘a surprisingly useful idea’?', 'Idea là head, quyết định cụm thuộc loại noun phrase; a thiết lập kiểu reference, useful phân loại/mô tả idea, surprisingly bổ nghĩa mức độ cho useful.', 'Tìm head trước giúp phân tích các cụm dài theo quan hệ thay vì đọc từng từ như một chuỗi ngang.', 'Từ đầu tiên của noun phrase luôn là head.', 'Tìm head và các dependent trong ‘the three messages from Hoàng’.', 'Trong ‘the three messages from Hoàng’, messages là head; the thiết lập definite reference; three cho số lượng; from Hoàng là dependent thu hẹp nguồn của messages.', ARRAY['noun-phrase', 'determiner', 'reference']::text[], ARRAY['core-en-module-05']::text[], ARRAY['claude-owner-paste:english-2026-08-25', 'english-core-sources:v1', 'core-synthesis:english-generative-core-v1', 'english-core-transfer-answers-v1']::text[], 'published', 'codex', 'hiep'),
  ('core-en-35', 'core-en-module-05', 'mechanism', 'Countability là nhãn cố định của từ hay cách đóng gói nghĩa trong ngữ cảnh? Dùng ‘chicken’ làm ví dụ.', 'Nhiều noun có thể được conceptualize theo hai cách: ‘a chicken’ là một cá thể đếm được, còn ‘some chicken’ có thể là vật chất/thức ăn không đếm theo đơn vị đó.', 'Countability tương tác với nghĩa đang chọn, vì vậy phải học pattern của từng sense chứ không dán một nhãn vĩnh viễn lên spelling.', 'Một noun đã được liệt kê uncountable thì không bao giờ đi với a/an.', 'Giải thích hai cách đóng gói ‘paper’ trong ‘a paper’ và ‘some paper’.', '‘I submitted a paper’ đóng gói paper như một bài báo/bài luận đếm được. ‘I need some paper’ đóng gói nó như vật liệu không đếm theo từng tờ cụ thể.', ARRAY['determiner', 'noun-phrase', 'reference']::text[], ARRAY['core-en-module-05']::text[], ARRAY['claude-owner-paste:english-2026-08-25', 'english-core-sources:v1', 'core-synthesis:english-generative-core-v1', 'english-core-transfer-answers-v1']::text[], 'published', 'codex', 'hiep'),
  ('core-en-36', 'core-en-module-05', 'contrast', 'Đối chiếu ‘I saw a dog’ và ‘The dog followed me’: vì sao article đổi dù vẫn là một con chó?', 'A giới thiệu một cá thể chưa được xác định chung; the cho biết người nói kỳ vọng người nghe nhận diện được cá thể đã được đưa vào discourse.', 'Article đánh dấu trạng thái reference giữa người nói, người nghe và ngữ cảnh, không đơn giản là dịch ‘một’ và ‘cái’.', 'The chỉ dùng cho vật duy nhất trên thế giới, còn a luôn nghĩa đúng số lượng một.', 'Viết hai câu giới thiệu rồi nhắc lại một cuốn sách bằng a/the.', '‘I found a useful book yesterday. The book explains English clauses clearly.’ A book giới thiệu referent mới; the book nhắc lại referent mà cả hai bên giờ đã nhận diện được.', ARRAY['reference', 'discourse', 'noun-phrase']::text[], ARRAY['core-en-module-05', 'core-en-module-07']::text[], ARRAY['claude-owner-paste:english-2026-08-25', 'english-core-sources:v1', 'core-synthesis:english-generative-core-v1', 'english-core-transfer-answers-v1']::text[], 'published', 'codex', 'hiep'),
  ('core-en-37', 'core-en-module-05', 'boundary', 'Vì sao không thể dùng một quy tắc ‘noun số ít có a, noun số nhiều không article’ cho mọi reference?', 'Proper names, mass nouns, generic reference và ngữ cảnh nhận diện tạo nhiều pattern khác; article phụ thuộc countability, number, definiteness và loại meaning.', 'Ranh giới này ngăn việc sửa article bằng một công thức bề mặt mà bỏ qua ý người nói.', 'Zero article chỉ là bỏ quên article chứ không mang thông tin.', 'So sánh generic meaning trong ‘Dogs are social animals’ với một nhóm cụ thể trong ‘The dogs are outside’.', '‘Dogs are social animals’ nói khái quát về loài/nhóm nói chung. ‘The dogs are outside’ chỉ một nhóm chó cụ thể mà người nghe có thể nhận diện từ ngữ cảnh.', ARRAY['determiner', 'noun-phrase', 'reference']::text[], ARRAY['core-en-module-05']::text[], ARRAY['claude-owner-paste:english-2026-08-25', 'english-core-sources:v1', 'core-synthesis:english-generative-core-v1', 'english-core-transfer-answers-v1']::text[], 'published', 'codex', 'hiep'),
  ('core-en-38', 'core-en-module-05', 'application', 'Chọn và giải thích determiner trong ngữ cảnh: bạn cần một ít thông tin nhưng chưa biết chính xác thông tin nào.', 'Có thể hỏi ‘Do you have any information?’ hoặc nói ‘I need some information’; information được đóng gói như mass noun và some/any phụ thuộc loại mệnh đề cùng kỳ vọng ngữ cảnh.', 'Chọn determiner từ meaning/reference trước giúp tránh ghép máy móc theo bản dịch tiếng Việt.', 'Any chỉ đi trong câu phủ định, some chỉ đi trong câu khẳng định.', 'Tạo một lời mời tự nhiên dùng some và một câu hỏi trung tính dùng any.', 'Lời mời: ‘Would you like some tea?’—some phù hợp vì người nói nghiêng về việc có trà để mời. Câu hỏi trung tính: ‘Do you have any tea?’—any không giả định mạnh rằng trà sẵn có.', ARRAY['noun-phrase', 'modifier', 'reference']::text[], ARRAY['core-en-module-03', 'core-en-module-05']::text[], ARRAY['claude-owner-paste:english-2026-08-25', 'english-core-sources:v1', 'core-synthesis:english-generative-core-v1', 'english-core-transfer-answers-v1']::text[], 'published', 'codex', 'hiep'),
  ('core-en-39', 'core-en-module-05', 'production', 'Tự sửa và giải thích câu ‘I bought book yesterday’ theo hai ý định khác nhau.', 'Nếu giới thiệu một cuốn bất kỳ: ‘I bought a book yesterday.’ Nếu cả hai đã biết cuốn nào: ‘I bought the book yesterday.’ Article phải khớp reference dự định.', 'Đưa ra hai bản sửa chứng minh rằng lỗi article không thể tách khỏi ngữ cảnh người nói-người nghe.', 'Chỉ có một đáp án article đúng cho mọi câu đứng riêng.', 'Làm tương tự với ‘Please close door’ trong hai bối cảnh khác nhau.', 'Nếu chỉ có một cánh cửa dễ nhận diện: ‘Please close the door.’ Nếu người nghe có thể chọn bất kỳ cửa nào trong nhiều cửa: ‘Please close a door,’ dù ngữ cảnh này ít tự nhiên hơn và cần mục đích rõ.', ARRAY['valency', 'complement', 'clause']::text[], ARRAY['core-en-module-05']::text[], ARRAY['claude-owner-paste:english-2026-08-25', 'english-core-sources:v1', 'core-synthesis:english-generative-core-v1', 'english-core-transfer-answers-v1']::text[], 'published', 'codex', 'hiep'),
  ('core-en-40', 'core-en-module-05', 'production', 'Tạo hai câu liên tiếp giới thiệu một người rồi nhắc lại người đó mà không gây mơ hồ.', 'Ví dụ ‘A woman entered the room. She was carrying a blue folder.’ Noun phrase đầu thiết lập referent; pronoun sau duy trì reference khi ngữ cảnh đủ rõ.', 'Reference chạy xuyên discourse, nên lựa chọn noun phrase/pronoun phải giúp người nghe theo dõi cùng một thực thể.', 'Pronoun luôn rõ vì nó thay thế noun đã xuất hiện gần nhất.', 'Thêm một người thứ hai rồi sửa câu nhắc lại để loại bỏ mơ hồ của ‘she/he/they’.', '‘A woman and a girl entered. The woman was carrying a blue folder.’ Dùng the woman thay she để loại mơ hồ khi có hai referent nữ cùng cạnh tranh.', ARRAY['noun-phrase', 'reference', 'discourse', 'determiner']::text[], ARRAY['core-en-module-05', 'core-en-module-07']::text[], ARRAY['claude-owner-paste:english-2026-08-25', 'english-core-sources:v1', 'core-synthesis:english-generative-core-v1', 'english-core-transfer-answers-v1']::text[], 'published', 'codex', 'hiep'),
  ('core-en-41', 'core-en-module-06', 'core_recall', 'Complement và adjunct khác nhau ở quan hệ với head như thế nào? Dùng ‘put the keys on the table yesterday’.', 'The keys và on the table hoàn thiện pattern nghĩa do put lựa chọn; yesterday thêm hoàn cảnh thời gian tương đối tự do nên là adjunct.', 'Phân biệt thành phần được head cấp phép với thông tin bổ sung giúp tự sinh và chẩn đoán câu thiếu.', 'Mọi cụm đứng sau verb đều là object hoặc adjunct tùy độ dài.', 'Phân tích ‘She depends on her team completely’ theo complement và adjunct.', 'Trong ‘She depends on her team completely’, on her team là complement được sense depend lựa chọn; completely là adjunct/degree modifier thêm mức độ và có thể bỏ mà pattern depend on vẫn còn.', ARRAY['complement', 'adjunct', 'valency']::text[], ARRAY['core-en-module-01', 'core-en-module-05']::text[], ARRAY['claude-owner-paste:english-2026-08-25', 'english-core-sources:v1', 'core-synthesis:english-generative-core-v1', 'english-core-transfer-answers-v1']::text[], 'published', 'codex', 'hiep'),
  ('core-en-42', 'core-en-module-06', 'mechanism', 'Vì sao biết nghĩa của verb vẫn chưa đủ để biết câu cần những complement nào?', 'Mỗi sense của verb đi với một valency pattern: sleep thường không cần object, give thường mở vai người cho-vật cho-người nhận, depend thường chọn on-phrase.', 'Học verb cùng pattern giúp sinh câu và tránh bê nguyên cấu trúc của từ gần nghĩa hoặc của tiếng Việt.', 'Mọi verb có thể nhận object nếu người nghe đoán được.', 'So sánh pattern của ‘say’ và ‘tell’ trong một thông điệp giống nhau.', '‘She said the message was urgent’ dùng say + content. ‘She told me the message was urgent’ dùng tell + recipient + content; ‘tell the message’ hoặc ‘say me’ không giữ đúng valency pattern thông thường.', ARRAY['complement', 'adjunct', 'clause']::text[], ARRAY['core-en-module-02', 'core-en-module-06']::text[], ARRAY['claude-owner-paste:english-2026-08-25', 'english-core-sources:v1', 'core-synthesis:english-generative-core-v1', 'english-core-transfer-answers-v1']::text[], 'published', 'codex', 'hiep'),
  ('core-en-43', 'core-en-module-06', 'mechanism', 'Subordination cho phép một clause làm thành phần trong clause lớn hơn ra sao trong ‘I know that she left’?', 'That she left là subordinate clause làm complement của know; clause lớn đóng gói một mệnh đề như nội dung của việc biết.', 'Cơ chế nhúng giúp từ các clause nhỏ tạo suy nghĩ phức tạp mà vẫn giữ quan hệ chính-phụ rõ.', 'Câu dài chỉ là nhiều câu ngắn nối bằng and.', 'Nhúng ‘the train is late’ sau một verb chỉ niềm tin hoặc phát hiện.', '‘I believe that the train is late.’ That the train is late là subordinate clause làm complement, tức nội dung của believe.', ARRAY['clause', 'subordination', 'complement']::text[], ARRAY['core-en-module-01', 'core-en-module-06']::text[], ARRAY['claude-owner-paste:english-2026-08-25', 'english-core-sources:v1', 'core-synthesis:english-generative-core-v1', 'english-core-transfer-answers-v1']::text[], 'published', 'codex', 'hiep'),
  ('core-en-44', 'core-en-module-06', 'contrast', 'Đối chiếu coordination và subordination trong ‘I stayed, and it rained’ với ‘I stayed because it rained’.', 'And đặt hai clause ở quan hệ phối hợp khá ngang hàng; because biến lý do thành subordinate clause phụ thuộc vào mệnh đề chính.', 'Connector không chỉ nối câu; nó mã hóa loại quan hệ logic mà người nói muốn người nghe xây dựng.', 'And, because và although chỉ khác phong cách, không đổi quan hệ nghĩa.', 'Diễn đạt cùng hai sự việc bằng although rồi mô tả quan hệ mới.', '‘Although it rained, I stayed.’ Although biến việc trời mưa thành concession: nó tạo kỳ vọng rằng mưa có thể khiến tôi đi, nhưng kết quả thực tế là tôi vẫn ở lại.', ARRAY['subordination', 'clause', 'complement']::text[], ARRAY['core-en-module-06']::text[], ARRAY['claude-owner-paste:english-2026-08-25', 'english-core-sources:v1', 'core-synthesis:english-generative-core-v1', 'english-core-transfer-answers-v1']::text[], 'published', 'codex', 'hiep'),
  ('core-en-45', 'core-en-module-06', 'boundary', 'Vì sao relative clause có dấu phẩy và không dấu phẩy không thể luôn thay nhau?', 'Integrated relative có thể giúp xác định referent, như ‘students who practised’; supplementary relative thêm thông tin bên lề về referent đã xác định và thường được ngăn bằng dấu phẩy/intonation.', 'Khác biệt là cách relative clause tham gia reference, không chỉ là quy tắc chấm câu trang trí.', 'Hễ có which thì luôn dùng dấu phẩy, hễ có that thì nghĩa không đổi.', 'So sánh nghĩa của ‘My brothers who live abroad...’ và ‘My brothers, who live abroad,...’ trong một gia đình có nhiều anh em.', '‘My brothers who live abroad visit in summer’ có thể ngụ ý chỉ những người anh/em sống ở nước ngoài mới thăm. ‘My brothers, who live abroad, visit in summer’ trình bày việc sống ở nước ngoài như thông tin thêm về toàn bộ nhóm brothers đã xác định.', ARRAY['relative-clause', 'noun-phrase', 'modifier', 'reference']::text[], ARRAY['core-en-module-05', 'core-en-module-06']::text[], ARRAY['claude-owner-paste:english-2026-08-25', 'english-core-sources:v1', 'core-synthesis:english-generative-core-v1', 'english-core-transfer-answers-v1']::text[], 'published', 'codex', 'hiep'),
  ('core-en-46', 'core-en-module-06', 'application', 'Mở rộng clause ‘The child found the key’ bằng một modifier trong noun phrase, một adjunct và một subordinate clause mà vẫn giữ trung tâm rõ.', 'Ví dụ ‘The tired child found the missing key under the sofa after everyone had left.’ Trung tâm vẫn là child–found–key; các lớp thêm nhận diện, nơi chốn và quan hệ thời gian.', 'Mở rộng theo tầng quanh head giúp câu giàu thông tin mà không mất cấu trúc lõi.', 'Câu càng nhiều modifier càng chính xác và càng hay.', 'Bỏ từng lớp khỏi câu mẫu và nói lớp nào là lõi, lớp nào có thể bỏ theo mục đích.', 'Lõi là ‘The child found the key.’ Bỏ tired/missing mất mô tả; bỏ under the sofa mất nơi chốn; bỏ after everyone had left mất quan hệ thời gian. Các lớp đó có thể bỏ nếu mục đích chỉ là kể sự kiện tìm thấy.', ARRAY['relative-clause', 'modifier', 'complement', 'clause']::text[], ARRAY['core-en-module-05', 'core-en-module-06']::text[], ARRAY['claude-owner-paste:english-2026-08-25', 'english-core-sources:v1', 'core-synthesis:english-generative-core-v1', 'english-core-transfer-answers-v1']::text[], 'published', 'codex', 'hiep'),
  ('core-en-47', 'core-en-module-06', 'production', 'Kết hợp ba ý ‘Hoàng opened the file. The file was corrupted. He called me.’ thành một câu có quan hệ rõ, không chỉ dùng and hai lần.', 'Một khả năng: ‘When Hoàng opened the corrupted file, he called me.’ Cách ghép phải thể hiện đúng quan hệ thời gian/nguyên nhân dự định; nếu chưa biết nguyên nhân thì không nên tự thêm because.', 'Production tốt đòi hỏi chọn quan hệ logic trước rồi mới chọn coordination, subordination hay modification.', 'Kết hợp câu cho phép tự suy ra mọi quan hệ hợp lý giữa các sự việc.', 'Viết một bản khác giữ ba ý nhưng nhấn mạnh việc file bị hỏng.', '‘Hoàng opened the file, which was corrupted, and then called me.’ Relative clause foregrounds trạng thái corrupted của file mà không khẳng định đó là nguyên nhân cuộc gọi; then giữ quan hệ thời gian.', ARRAY['clause', 'modifier', 'subordination', 'adjunct']::text[], ARRAY['core-en-module-06', 'core-en-module-07']::text[], ARRAY['claude-owner-paste:english-2026-08-25', 'english-core-sources:v1', 'core-synthesis:english-generative-core-v1', 'english-core-transfer-answers-v1']::text[], 'published', 'codex', 'hiep'),
  ('core-en-48', 'core-en-module-06', 'production', 'Tự tạo một câu phức rồi rút nó về clause lõi; giải thích mỗi phần mở rộng phục vụ người nghe ra sao.', 'Đáp án đạt yêu cầu phải chỉ ra clause lõi có head/roles rõ và gắn từng complement, modifier hoặc adjunct với một chức năng nghĩa cụ thể.', 'Thao tác mở rộng rồi rút gọn kiểm tra người học còn thấy cấu trúc sinh bên dưới câu dài.', 'Phân tích được tên thành phần là đủ, không cần biết thông tin nào đang giúp người nghe.', 'Đổi hoặc bỏ một phần mở rộng và mô tả chính xác nghĩa/reference thay đổi.', 'Ví dụ ‘The student who sits near me submitted the assignment after class.’ Lõi là ‘The student submitted the assignment’; who sits near me xác định student, after class thêm thời gian. Bỏ relative clause có thể làm reference kém rõ; bỏ adjunct chỉ mất thời điểm.', ARRAY['clause', 'complement', 'modifier', 'subordination', 'relative-clause']::text[], ARRAY['core-en-module-06']::text[], ARRAY['claude-owner-paste:english-2026-08-25', 'english-core-sources:v1', 'core-synthesis:english-generative-core-v1', 'english-core-transfer-answers-v1']::text[], 'published', 'codex', 'hiep'),
  ('core-en-49', 'core-en-module-07', 'core_recall', 'Nguyên lý given → new giúp người nói tổ chức câu cho người nghe như thế nào?', 'Người nói thường neo câu vào thông tin đang hoạt động hoặc dễ nhận diện, rồi đưa phần mới hay trọng tâm sau; đây là xu hướng discourse chứ không phải thứ tự bất biến.', 'Tổ chức thông tin giải thích vì sao nhiều câu đều đúng ngữ pháp nhưng chỉ một câu nối tự nhiên với câu hỏi hoặc ngữ cảnh trước.', 'Given luôn phải là subject và new luôn phải là object cuối câu.', 'Sau câu ‘I bought a lamp’, chọn cách mở câu tiếp theo để nói thêm về chiếc đèn.', '‘I bought a lamp. It gives the room a warm light.’ It neo câu mới vào chiếc lamp đã given; phần gives the room a warm light mang thông tin mới.', ARRAY['discourse', 'reference', 'clause']::text[], ARRAY['core-en-module-01', 'core-en-module-05']::text[], ARRAY['claude-owner-paste:english-2026-08-25', 'english-core-sources:v1', 'core-synthesis:english-generative-core-v1', 'english-core-transfer-answers-v1']::text[], 'published', 'codex', 'hiep'),
  ('core-en-50', 'core-en-module-07', 'mechanism', 'Câu hỏi trước đó quyết định focus của câu trả lời thế nào trong ‘Mai bought the red book’?', 'Nếu hỏi ‘Who bought it?’, focus là Mai; nếu hỏi ‘What did Mai buy?’, focus là the red book. Cùng word order có thể mang focus khác qua context và prominence.', 'Focus là quan hệ giữa utterance và alternatives trong discourse, không chỉ là từ cuối câu.', 'Từ được nhấn hoặc đứng cuối luôn chứa thông tin hoàn toàn mới.', 'Đặt hai câu hỏi khác nhau để cùng câu trả lời trên trả lời tự nhiên với focus khác.', 'Câu hỏi 1: ‘Who bought the red book?’—focus tự nhiên là Mai. Câu hỏi 2: ‘Which book did Mai buy?’—focus là the red book. Cùng câu trả lời nhưng context quyết định phần được coi là mới.', ARRAY['discourse', 'prosody', 'clause']::text[], ARRAY['core-en-module-07', 'core-en-module-08']::text[], ARRAY['claude-owner-paste:english-2026-08-25', 'english-core-sources:v1', 'core-synthesis:english-generative-core-v1', 'english-core-transfer-answers-v1']::text[], 'published', 'codex', 'hiep'),
  ('core-en-51', 'core-en-module-07', 'mechanism', 'Active và passive thay đổi cách đóng gói cùng một sự việc ra sao trong ‘A storm damaged the roof’ / ‘The roof was damaged by a storm’?', 'Active đặt tác nhân a storm làm subject; passive đưa patient the roof lên subject và có thể giữ hoặc bỏ tác nhân, nên thay đổi điểm xuất phát và luồng thông tin.', 'Passive là lựa chọn về clause structure và discourse perspective, không đơn giản là đổi từ cho trang trọng.', 'Passive luôn che giấu người chịu trách nhiệm và không dùng trong văn nói.', 'Chọn active hoặc passive để tiếp câu ‘Let me tell you what happened to the roof’ và giải thích.', '‘The roof was damaged by a storm.’ Passive phù hợp vì câu trước đã đặt the roof làm chủ đề; câu mới tiếp tục từ roof rồi mới đưa tác nhân a storm.', ARRAY['clause', 'subject', 'object', 'discourse']::text[], ARRAY['core-en-module-02', 'core-en-module-07']::text[], ARRAY['claude-owner-paste:english-2026-08-25', 'english-core-sources:v1', 'core-synthesis:english-generative-core-v1', 'english-core-transfer-answers-v1']::text[], 'published', 'codex', 'hiep'),
  ('core-en-52', 'core-en-module-07', 'contrast', 'Đối chiếu ‘Lan solved the problem’ và ‘It was Lan who solved the problem’: cleft thêm điều gì ngoài độ dài?', 'Cleft cấu trúc hóa Lan thành focus đối chiếu, thường bác bỏ hoặc chọn giữa alternatives; câu thường chỉ kể sự việc nếu không có ngữ cảnh nhấn tương ứng.', 'Các construction khác nhau cho phép người nói điều khiển focus mà không đổi các participant chính.', 'Cleft là cách viết trang trọng hơn và dùng lúc nào cũng hay hơn.', 'Tạo một ngữ cảnh trong đó cleft sửa một hiểu lầm về người giải bài.', 'A: ‘Did Hoàng solve the problem?’ B: ‘No, it was Lan who solved the problem.’ Cleft chọn Lan trong tập người có thể giải và sửa hiểu lầm rằng Hoàng là người làm.', ARRAY['discourse', 'reference', 'prosody']::text[], ARRAY['core-en-module-07']::text[], ARRAY['claude-owner-paste:english-2026-08-25', 'english-core-sources:v1', 'core-synthesis:english-generative-core-v1', 'english-core-transfer-answers-v1']::text[], 'published', 'codex', 'hiep'),
  ('core-en-53', 'core-en-module-07', 'boundary', 'Vì sao không thể dùng ‘đưa thông tin mới xuống cuối’ như một luật cứng?', 'Focus còn được đánh dấu bằng prominence, construction và context; câu hỏi, heavy constituents, style hoặc contrast có thể tạo trật tự khác mà vẫn tự nhiên.', 'Given/new là công cụ dự đoán và chỉnh discourse, không thay thế cú pháp hay ngữ cảnh thực.', 'Bất kỳ câu nào có new information ở đầu đều sai hoặc khó hiểu.', 'Tìm một lời đáp ngắn như ‘A DOG bit me’ trong đó phần mới/đối chiếu xuất hiện sớm và giải thích ngữ cảnh.', 'Ngữ cảnh: ‘I thought a cat scratched you.’—‘No, A DOG bit me.’ A dog xuất hiện sớm nhưng vẫn là contrastive new focus nhờ prominence và đối lập với cat.', ARRAY['discourse', 'reference', 'noun-phrase']::text[], ARRAY['core-en-module-07', 'core-en-module-08']::text[], ARRAY['claude-owner-paste:english-2026-08-25', 'english-core-sources:v1', 'core-synthesis:english-generative-core-v1', 'english-core-transfer-answers-v1']::text[], 'published', 'codex', 'hiep'),
  ('core-en-54', 'core-en-module-07', 'application', 'Sắp xếp lại hai câu ‘A strange package arrived. A courier left it at the door’ để kể tiếp sau chủ đề ‘the package’.', 'Có thể dùng ‘A strange package arrived. It had been left at the door by a courier.’ Pronoun/passive giữ the package làm điểm neo; lựa chọn cuối cùng phụ thuộc timeline dự định.', 'Reference, voice và tense/aspect phối hợp để giữ mạch, không có một phép đổi riêng lẻ giải quyết mọi discourse.', 'Dùng passive luôn làm đoạn văn mạch lạc hơn active.', 'Viết một bản active tự nhiên nếu câu trước đang nói về courier.', 'Nếu câu trước đang nói về courier: ‘The courier reached our building at noon. He left a strange package at the door.’ Active giữ courier làm điểm neo/given subject.', ARRAY['reference', 'discourse', 'noun-phrase']::text[], ARRAY['core-en-module-04', 'core-en-module-05', 'core-en-module-07']::text[], ARRAY['claude-owner-paste:english-2026-08-25', 'english-core-sources:v1', 'core-synthesis:english-generative-core-v1', 'english-core-transfer-answers-v1']::text[], 'published', 'codex', 'hiep'),
  ('core-en-55', 'core-en-module-07', 'production', 'Trả lời câu ‘Why did Hiệp leave early?’ bằng một câu có focus đúng, rồi đổi câu trả lời cho câu hỏi ‘Who left early?’.', 'Cho why: ‘He left early because he felt ill’ đặt lý do làm thông tin cần cung cấp. Cho who: ‘HIỆP left early’ đặt người làm contrastive focus; chữ hoa chỉ mô phỏng prominence.', 'Tạo câu từ câu hỏi giao tiếp giúp người học nối grammar, order và spoken focus.', 'Một câu trả lời ngữ pháp đúng sẽ phù hợp như nhau với mọi câu hỏi.', 'Thu âm hoặc đọc hai câu với prominence khác nhau và kiểm tra phần nào người nghe dự đoán là mới.', 'Trong ‘HIỆP left early’, prominence ở Hiệp trả lời who. Trong ‘Hiệp left EARLY’, prominence ở early sửa thời điểm. Người nghe dự đoán phần nổi bật là thông tin mới hoặc đối chiếu.', ARRAY['prosody', 'discourse']::text[], ARRAY['core-en-module-07', 'core-en-module-08']::text[], ARRAY['claude-owner-paste:english-2026-08-25', 'english-core-sources:v1', 'core-synthesis:english-generative-core-v1', 'english-core-transfer-answers-v1']::text[], 'published', 'codex', 'hiep'),
  ('core-en-56', 'core-en-module-07', 'production', 'Viết ba câu về một vật mới, duy trì reference và đưa mỗi câu thêm đúng một lớp thông tin mới.', 'Một đoạn đạt yêu cầu giới thiệu referent bằng noun phrase, nhắc lại rõ bằng pronoun/definite phrase, rồi sắp thông tin mới để người đọc không phải đoán referent thay đổi.', 'Bài production tích hợp article, pronoun, voice và given/new thành mạch discourse thay vì học từng quy tắc rời.', 'Lặp cùng noun đầy đủ ở đầu mọi câu luôn là cách rõ nhất.', 'Thêm một referent cạnh tranh và sửa các biểu thức nhắc lại để vẫn không mơ hồ.', '‘A new laptop arrived. It has a bright screen. The laptop also runs quietly. A tablet arrived later, but the laptop was faster.’ Khi tablet xuất hiện, dùng the laptop thay it để tránh mơ hồ.', ARRAY['discourse', 'clause', 'subject', 'object', 'prosody']::text[], ARRAY['core-en-module-05', 'core-en-module-07']::text[], ARRAY['claude-owner-paste:english-2026-08-25', 'english-core-sources:v1', 'core-synthesis:english-generative-core-v1', 'english-core-transfer-answers-v1']::text[], 'published', 'codex', 'hiep'),
  ('core-en-57', 'core-en-module-08', 'core_recall', 'Vì sao nghe tiếng Anh không thể chỉ là nhận từng từ có khoảng trắng như trên trang giấy?', 'Lời nói là dòng âm liên tục được tổ chức thành syllable, prominence và phrase; âm có thể yếu, nối hoặc biến đổi, nên người nghe phải suy ra ranh giới từ nhờ cả tín hiệu âm lẫn ngữ cảnh.', 'Listening là bài toán segmentation và dự đoán cấu trúc/meaning, không chỉ tra từ đã phát âm ở dạng từ điển.', 'Người bản ngữ luôn phát âm thiếu chữ nên chỉ cần quen tốc độ nhanh.', 'Nghe hoặc tự nói ‘Can you send it?’ và đánh dấu nơi bạn dự đoán ranh giới từ dù âm nối liền.', 'Có thể dự đoán các từ là can | you | send | it, nhưng khi nói nhanh /kənjə sendɪt/ các biên nối nhau. Cấu trúc modal + subject + base verb + object và nghĩa request giúp khôi phục ranh giới.', ARRAY['phoneme', 'prosody']::text[], ARRAY['core-en-module-07']::text[], ARRAY['claude-owner-paste:english-2026-08-25', 'english-core-sources:v1', 'core-synthesis:english-generative-core-v1', 'english-core-transfer-answers-v1']::text[], 'published', 'codex', 'hiep'),
  ('core-en-58', 'core-en-module-08', 'mechanism', 'Prominence giúp người nghe tìm thông tin quan trọng thế nào trong ‘I wanted the BLUE one’?', 'Syllable nổi bật ở BLUE thu hẹp alternatives và báo contrast/focus; các từ chức năng xung quanh có thể ít nổi hơn nhưng vẫn mang cấu trúc.', 'Nghe trọng âm câu theo ý nghĩa giúp tìm focus thay vì cố nghe mọi âm với trọng lượng ngang nhau.', 'Content word luôn được nhấn, function word luôn không được nhấn.', 'Đổi prominence sang I hoặc wanted và tạo ngữ cảnh làm mỗi cách đọc hợp lý.', '‘I wanted the blue one’ với prominence ở I hợp khi sửa ‘Hoàng wanted it’. Prominence ở wanted hợp khi sửa hiểu lầm ‘I bought the blue one’; cùng segment nhưng contrast thay đổi.', ARRAY['phoneme', 'prosody']::text[], ARRAY['core-en-module-07', 'core-en-module-08']::text[], ARRAY['claude-owner-paste:english-2026-08-25', 'english-core-sources:v1', 'core-synthesis:english-generative-core-v1', 'english-core-transfer-answers-v1']::text[], 'published', 'codex', 'hiep'),
  ('core-en-59', 'core-en-module-08', 'mechanism', 'Weak form và schwa xuất hiện do cơ chế nào, và vì sao chúng làm từ quen trở nên khó nhận?', 'Trong syllable không nổi bật, vowel có thể trung hòa về schwa và function word rút gọn; từ vẫn được nhận nhờ rhythm, phrase và context chứ không giữ nguyên dạng citation rõ từng âm.', 'Học cặp strong/weak trong utterance thật nối spelling với biến thiên có điều kiện.', 'Schwa là cách phát âm cẩu thả cần tránh hoàn toàn khi nói.', 'So sánh ‘I CAN do it’ với ‘I can DO it’ và mô tả can thay đổi theo prominence.', 'Trong ‘I CAN do it’, can nổi bật và thường giữ vowel rõ để bác bỏ nghi ngờ về khả năng. Trong ‘I can DO it’, can thường yếu /kən/, còn do nhận prominence vì hành động hoàn thành là focus.', ARRAY['prosody', 'phoneme', 'discourse']::text[], ARRAY['core-en-module-08']::text[], ARRAY['claude-owner-paste:english-2026-08-25', 'english-core-sources:v1', 'core-synthesis:english-generative-core-v1', 'english-core-transfer-answers-v1']::text[], 'published', 'codex', 'hiep'),
  ('core-en-60', 'core-en-module-08', 'contrast', 'Phân biệt lỗi segment với lỗi prominence/intonation: vì sao phát âm đúng từng phụ âm-nguyên âm vẫn có thể khó hiểu?', 'Segment là đơn vị âm như /p/ hay vowel; prominence và intonation tổ chức chúng thành focus, grouping và thái độ. Cả hai tầng đều góp phần nhận diện, nhưng vấn đề ở một tầng không tự chứng minh tầng kia sai.', 'Chẩn đoán theo tầng giúp chọn bài sửa: minimal contrast cho segment, chunk/focus practice cho prosody.', 'Chỉ cần IPA chính xác từng từ là câu tự nhiên và dễ nghe.', 'Nói cùng chuỗi ‘You finished’ như lời xác nhận và như câu hỏi ngạc nhiên; điều gì đổi ngoài segment?', 'Segments của ‘You finished’ có thể giữ nguyên. Intonation xuống biến nó thành xác nhận/kết luận; intonation lên hoặc contour ngạc nhiên biến nó thành câu hỏi/không tin. Grouping và pitch đổi, không nhất thiết đổi phụ âm-nguyên âm.', ARRAY['phoneme', 'prosody', 'discourse']::text[], ARRAY['core-en-module-08']::text[], ARRAY['claude-owner-paste:english-2026-08-25', 'english-core-sources:v1', 'core-synthesis:english-generative-core-v1', 'english-core-transfer-answers-v1']::text[], 'published', 'codex', 'hiep'),
  ('core-en-61', 'core-en-module-08', 'boundary', 'Vì sao nhãn ‘stress-timed English’ chỉ nên dùng như heuristic, không như nhịp máy cố định?', 'Ngôn ngữ và người nói thay đổi về timing; prominence, syllable structure, reduction và tốc độ cùng tạo nhịp. Không có quy tắc mọi khoảng giữa stress phải bằng nhau.', 'Ranh giới này giữ giá trị thực hành của prominence/reduction mà không biến một phân loại rhythm thành định luật.', 'Muốn nói tự nhiên phải ép mọi stressed syllable cách nhau đúng cùng số mili-giây.', 'Đọc một câu chậm rồi nhanh nhưng giữ focus; quan sát phần nào co giãn mà meaning vẫn rõ.', 'Khi nói nhanh ‘I really need to finish this today’, function words và syllable không nổi bật co lại, linking tăng; prominence vẫn có thể ở finish hoặc today để giữ focus. Khoảng thời gian giữa các stress không cần bằng nhau tuyệt đối.', ARRAY['phoneme', 'prosody']::text[], ARRAY['core-en-module-08']::text[], ARRAY['claude-owner-paste:english-2026-08-25', 'english-core-sources:v1', 'core-synthesis:english-generative-core-v1', 'english-core-transfer-answers-v1']::text[], 'published', 'codex', 'hiep'),
  ('core-en-62', 'core-en-module-08', 'application', 'Khi nghe ‘Could you send it again?’, hãy dùng structure và prominence để khôi phục từ thay vì tua từng âm như thế nào?', 'Dự đoán đây là request có modal + subject + base verb + object; tìm syllable nổi bật như SEND/AGAIN, rồi dùng các weak chunks quanh chúng để kiểm tra giả thuyết.', 'Top-down prediction và bottom-up sound evidence phải kiểm tra lẫn nhau; đoán cấu trúc không có nghĩa bỏ qua tín hiệu âm.', 'Biết ngữ pháp cho phép điền bất kỳ từ nào hợp nghĩa dù âm thanh không khớp.', 'Thay send bằng một verb khác, tự nói nhanh tự nhiên rồi chép lại sau một lần nghe bản ghi.', 'Thay send bằng check: ‘Could you check it again?’ Khi nói nhanh, dự đoán modal could + you + base check + object it + again; prominence thường rơi vào CHECK/AGAIN và các weak chunks nối quanh đó.', ARRAY['phoneme', 'clause', 'prosody']::text[], ARRAY['core-en-module-03', 'core-en-module-08']::text[], ARRAY['claude-owner-paste:english-2026-08-25', 'english-core-sources:v1', 'core-synthesis:english-generative-core-v1', 'english-core-transfer-answers-v1']::text[], 'published', 'codex', 'hiep'),
  ('core-en-63', 'core-en-module-08', 'production', 'Chọn một câu ngắn, nghe rồi shadow theo chunk; bạn phải tự kiểm ba thứ gì ngoài ‘giống giọng’?', 'Kiểm ranh giới thought group, vị trí prominence và các weak/linking transitions; sau đó nói lại với meaning riêng thay vì bắt chước âm vô thức.', 'Shadowing có mục tiêu nối perception với production, còn sao chép accent bề mặt không bảo đảm hiểu hay transfer.', 'Shadow càng nhanh và càng giống người bản ngữ thì càng học tốt.', 'Giữ cấu trúc nhịp nhưng đổi một content word và đặt prominence mới phù hợp với meaning.', 'Từ ‘I NEED the blue one’, giữ thought group và nhịp nhưng đổi content word: ‘I WANT the blue one.’ Chuyển prominence sang BLUE nếu meaning mới là sửa màu, không phải sửa hành động want/need.', ARRAY['phoneme', 'prosody', 'discourse']::text[], ARRAY['core-en-module-08']::text[], ARRAY['claude-owner-paste:english-2026-08-25', 'english-core-sources:v1', 'core-synthesis:english-generative-core-v1', 'english-core-transfer-answers-v1']::text[], 'published', 'codex', 'hiep'),
  ('core-en-64', 'core-en-module-08', 'production', 'Sau khi nghe sai một câu, hãy tạo quy trình chẩn đoán thay vì chỉ nghe lại vô hạn.', 'Xác định sai ở từ vựng/cấu trúc, segmentation, segment, weak form hay prominence; kiểm transcript sau một lần tự đoán, nghe đoạn ngắn, rồi tự sản xuất một câu tương tự.', 'Một vòng có giả thuyết và transfer biến lỗi nghe thành dữ liệu học có thể tái dùng.', 'Nghe lặp đủ nhiều tự động sửa mọi loại lỗi mà không cần biết sai ở đâu.', 'Lấy một câu bạn từng nghe nhầm, phân loại lỗi và thiết kế một ví dụ mới để kiểm tra cùng cơ chế.', 'Ví dụ từng nghe nhầm ‘Did you send it?’ thành ‘Do you send it?’: lỗi nằm ở weak form/segmentation của did you. Kiểm transcript, nghe đoạn /dɪdʒə/, rồi tự tạo ‘Did you check it?’ để kiểm cùng cơ chế.', ARRAY['phoneme', 'prosody', 'discourse']::text[], ARRAY['core-en-module-08']::text[], ARRAY['claude-owner-paste:english-2026-08-25', 'english-core-sources:v1', 'core-synthesis:english-generative-core-v1', 'english-core-transfer-answers-v1']::text[], 'published', 'codex', 'hiep'),
  ('core-en-65', 'core-en-module-09', 'core_recall', 'Vì sao lexicon nên được học như mạng lưới form–meaning–use thay vì danh sách từ dịch một-một?', 'Một lexical item nối nhiều sense, word family, collocation, register và construction; biết các liên kết giúp dự đoán và sản xuất, còn bản dịch đơn chỉ cho một điểm truy cập.', 'Mạng lưới cho kiến thức mới bám vào node cũ và vẫn giữ chỗ cho ngoại lệ/convention.', 'Mỗi từ tiếng Anh có đúng một nghĩa tiếng Việt cốt lõi dùng được ở mọi câu.', 'Vẽ mạng nhỏ quanh ‘run’ gồm một sense, một pattern ngữ pháp và hai collocation khác nhau.', 'Mạng quanh run: sense ‘chạy bằng chân’; pattern run + distance/place như ‘run five kilometres’; collocations ‘run a business’ và ‘run out of time’. Các nhánh nối form run với nhiều meaning/use khác nhau.', ARRAY['collocation', 'reference']::text[], ARRAY['core-en-module-06', 'core-en-module-08']::text[], ARRAY['claude-owner-paste:english-2026-08-25', 'english-core-sources:v1', 'core-synthesis:english-generative-core-v1', 'english-core-transfer-answers-v1']::text[], 'published', 'codex', 'hiep'),
  ('core-en-66', 'core-en-module-09', 'mechanism', 'Tần suất cao giúp ưu tiên học từ như thế nào mà không biến con số 800–1000 thành lời hứa hiểu 80% mọi tiếng Anh?', 'Frequency giúp chọn item có khả năng tái xuất hiện cao, nhưng coverage thay đổi theo loại văn bản/lời nói, cách đếm word family và kiến thức multiword; không thể suy mức hiểu bằng phép cộng phần trăm máy móc.', 'Ưu tiên tần suất là chiến lược phân bổ công sức, không phải ngưỡng ma thuật bảo đảm comprehension.', 'Học xong một danh sách nghìn từ là đủ nghe đọc tự nhiên mà không cần context hay chunks.', 'Chọn năm từ/chunk từ một đoạn bạn thật sự dùng, kết hợp tần suất với mục tiêu cá nhân để xếp thứ tự học.', 'Từ một đoạn công việc có ‘send an email’, ‘check the file’, ‘meet the client’, ‘fix the bug’, ‘update the report’, có thể ưu tiên theo tần suất gặp trong việc thật và nhu cầu sắp tới: check the file → fix the bug → update the report → send an email → meet the client.', ARRAY['morpheme', 'clause', 'noun-phrase']::text[], ARRAY['core-en-module-09']::text[], ARRAY['claude-owner-paste:english-2026-08-25', 'english-core-sources:v1', 'core-synthesis:english-generative-core-v1', 'english-core-transfer-answers-v1']::text[], 'published', 'codex', 'hiep'),
  ('core-en-67', 'core-en-module-09', 'mechanism', 'Word family và morphology giúp suy nghĩa mới ra sao, và tại sao vẫn phải kiểm tra usage?', 'Prefix/suffix và base tạo giả thuyết về form/category/meaning, như teach→teacher; nhưng sense, stress, spelling và mức thông dụng có thể lexicalized nên cần kiểm tra corpus/dictionary đáng tin.', 'Morphology nén nhiều từ quanh một pattern nhưng không xóa convention.', 'Biết nghĩa prefix/suffix cho phép tự tạo bất kỳ từ nào và chắc chắn người khác dùng.', 'Từ ‘possible’, suy hai thành viên family rồi kiểm tra category và cách dùng trong câu.', 'Possible → impossible (adjective, ‘That is impossible’) và possibility (noun, ‘There is a possibility of rain’). Cần kiểm spelling, category và pattern complement thay vì cho rằng mọi suffix dùng giống nhau.', ARRAY['collocation', 'discourse']::text[], ARRAY['core-en-module-09']::text[], ARRAY['claude-owner-paste:english-2026-08-25', 'english-core-sources:v1', 'core-synthesis:english-generative-core-v1', 'english-core-transfer-answers-v1']::text[], 'published', 'codex', 'hiep'),
  ('core-en-68', 'core-en-module-09', 'contrast', 'Đối chiếu phrasal verb compositional và idiomatic bằng ‘walk out’ với ‘figure out’.', 'Walk out có thể suy khá trực tiếp từ motion + out; figure out có meaning conventional ‘hiểu/tìm ra’ khó cộng nghĩa từng phần. Nhiều phrasal verb nằm giữa hai cực và có extension theo hình ảnh không gian.', 'Dùng continuum giúp khai thác pattern khi có thể mà vẫn lưu những meaning phải học như chunk.', 'Mọi particle có một nghĩa cố định nên mọi phrasal verb đều suy được hoàn toàn.', 'Đặt ‘take off’ vào hai context và phân loại mức compositional của từng sense.', '‘The plane took off’ khá compositional theo hình ảnh rời mặt đất. ‘The new product really took off’ là extension conventional nghĩa trở nên thành công/phổ biến; sense này ít suy trực tiếp hơn và cần context.', ARRAY['collocation', 'reference']::text[], ARRAY['core-en-module-09']::text[], ARRAY['claude-owner-paste:english-2026-08-25', 'english-core-sources:v1', 'core-synthesis:english-generative-core-v1', 'english-core-transfer-answers-v1']::text[], 'published', 'codex', 'hiep'),
  ('core-en-69', 'core-en-module-09', 'boundary', 'Vì sao hiểu nghĩa từng từ chưa bảo đảm tạo collocation tự nhiên như ‘make a decision’?', 'Collocation là preference/convention về các từ thường đi cùng trong một sense/register; logic có thể gợi ý nhưng cộng đồng sử dụng quyết định pattern được chấp nhận và mức tự nhiên.', 'Nguyên lý semantic giúp đoán, còn input/corpus và retrieval xác nhận conventional combination.', 'Mọi tổ hợp đồng nghĩa đúng ngữ pháp đều tự nhiên như nhau.', 'So sánh ‘make a decision’ với một tổ hợp dịch sát từ tiếng Việt và nêu cách kiểm chứng thay vì chỉ tin trực giác.', 'Tiếng Việt có thể gợi tổ hợp sai như ‘do a decision’. Kiểm corpus/dictionary collocation cho thấy ‘make a decision’ là pattern thông dụng; dùng nguồn thay vì chỉ dịch từng từ hoặc tin cảm giác.', ARRAY['collocation', 'discourse', 'reference']::text[], ARRAY['core-en-module-09']::text[], ARRAY['claude-owner-paste:english-2026-08-25', 'english-core-sources:v1', 'core-synthesis:english-generative-core-v1', 'english-core-transfer-answers-v1']::text[], 'published', 'codex', 'hiep'),
  ('core-en-70', 'core-en-module-09', 'application', 'Bạn gặp chunk mới ‘take responsibility for’. Hãy phân tích và lưu nó thế nào để có thể tự dùng lại?', 'Lưu meaning trung tâm, pattern take + responsibility + for + noun/-ing, một ví dụ thật, contrast gần và một câu tự tạo; review bằng cách gọi cả chunk từ ý định.', 'Học node word cùng slot và context tạo khả năng biến đổi tốt hơn thuộc một câu đóng kín.', 'Chỉ cần ghi bản dịch ‘chịu trách nhiệm’ là đã biết cách dùng.', 'Tạo hai câu thay phần sau for và đổi tense của take mà vẫn giữ pattern.', '‘She took responsibility for fixing the error.’ ‘They will take responsibility for the project.’ Phần sau for đổi từ -ing clause sang noun phrase; take đổi sang past/will + base nhưng chunk constraint vẫn giữ.', ARRAY['collocation', 'clause', 'noun-phrase']::text[], ARRAY['core-en-module-06', 'core-en-module-09']::text[], ARRAY['claude-owner-paste:english-2026-08-25', 'english-core-sources:v1', 'core-synthesis:english-generative-core-v1', 'english-core-transfer-answers-v1']::text[], 'published', 'codex', 'hiep'),
  ('core-en-71', 'core-en-module-09', 'production', 'Tạo một semantic network nhỏ cho từ ‘break’ để tránh học các nghĩa như những mục hoàn toàn rời.', 'Một mạng đạt yêu cầu có prototype gây vật mất tính toàn vẹn, extension như break a rule/break the news, các pattern/collocation, và đánh dấu sense nào conventional cần ví dụ riêng.', 'Tự xây liên kết khuyến khích suy đoán có kiểm soát và nhớ nhờ quan hệ, không giả rằng mọi extension tất yếu.', 'Tìm được một hình ảnh gốc nghĩa là có thể suy chính xác mọi idiom chứa từ đó.', 'Dùng một context mới để dự đoán sense của break, sau đó nêu bằng chứng cần kiểm tra.', 'Trong ‘The news broke overnight’, dự đoán break nghĩa trở nên công khai/được phát ra, không phải vật thể vỡ. Cần kiểm dictionary/corpus và các collocation như breaking news để xác nhận sense conventional.', ARRAY['collocation', 'discourse', 'reference']::text[], ARRAY['core-en-module-09']::text[], ARRAY['claude-owner-paste:english-2026-08-25', 'english-core-sources:v1', 'core-synthesis:english-generative-core-v1', 'english-core-transfer-answers-v1']::text[], 'published', 'codex', 'hiep'),
  ('core-en-72', 'core-en-module-09', 'production', 'Chọn một collocation từ input thật và thiết kế ba lần retrieval có transfer thay vì chép lại ba lần.', 'Lần một gọi chunk từ meaning; lần hai điền node word trong context mới; lần ba tự nói câu phù hợp register. Các lần được giãn cách và phản hồi bằng nguồn đáng tin.', 'Spacing kết hợp variation giúp nhớ form–meaning connection và kiểm tra khả năng dùng ngoài câu gốc.', 'Cùng nhìn lại đáp án nhiều lần tạo retrieval mạnh như tự gọi từ trí nhớ.', 'Đổi subject, tense và object của chunk nhưng giữ collocational constraint cốt lõi.', 'Với ‘make a decision’: ‘She made a decision about the budget’; ‘They will make an important decision tomorrow.’ Subject, tense và object/topic đổi nhưng collocational core make + decision vẫn giữ.', ARRAY['morpheme', 'collocation', 'discourse', 'clause']::text[], ARRAY['core-en-module-09']::text[], ARRAY['claude-owner-paste:english-2026-08-25', 'english-core-sources:v1', 'core-synthesis:english-generative-core-v1', 'english-core-transfer-answers-v1']::text[], 'published', 'codex', 'hiep'),
  ('core-en-73', 'core-en-module-10', 'core_recall', 'Một quy trình tự sinh câu từ ý định đến lời nói có thể đi qua những tầng nào?', 'Chọn meaning/quan hệ, dựng clause roles và verb architecture, chọn tense-aspect-modality/reference, tổ chức information flow, lấy lexical chunks, rồi đóng gói thành sound/prosody và kiểm phản hồi.', 'Các tầng liên kết thành hệ thống sinh; thứ tự có thể lặp lại chứ không phải dây chuyền cứng.', 'Muốn nói nhanh phải bỏ qua cấu trúc và dịch trực tiếp câu tiếng Việt trong đầu.', 'Từ ý ‘Hoàng có thể đã quên chìa khóa’, đi qua từng tầng để tạo một câu và nêu lựa chọn của bạn.', 'Ý nghĩa: khả năng + việc quên đã xảy ra. Roles: Hoàng là experiencer/subject, the key là object. Kiến trúc: modal might + perfect have + participle forgotten. Câu: ‘Hoàng might have forgotten the key.’ Focus tự nhiên có thể ở key nếu đó là thông tin mới.', ARRAY['clause', 'finite-verb', 'tense', 'aspect', 'modality', 'reference']::text[], ARRAY['core-en-module-04', 'core-en-module-08', 'core-en-module-09']::text[], ARRAY['claude-owner-paste:english-2026-08-25', 'english-core-sources:v1', 'core-synthesis:english-generative-core-v1', 'english-core-transfer-answers-v1']::text[], 'published', 'codex', 'hiep'),
  ('core-en-74', 'core-en-module-10', 'mechanism', 'Làm sao dùng một clause lõi để tạo ‘ma trận biến đổi’ mà vẫn hiểu mỗi thay đổi?', 'Giữ roles/lexical event ổn định rồi lần lượt đổi polarity, question, tense/aspect/modality, voice, reference hoặc focus; sau mỗi đổi phải nói meaning/discourse effect thay vì chỉ đổi form.', 'Một clause sinh nhiều nhánh cho phép thấy cơ chế dùng lại và ranh giới tương tác giữa chúng.', 'Biến đổi càng nhiều dạng càng tốt dù câu không có context sử dụng.', 'Từ ‘The team solved the problem’, tạo question, passive và modal-perfect, giải thích từng lớp.', 'Question: ‘Did the team solve the problem?’—did mang past. Passive: ‘The problem was solved by the team’—problem thành subject/patient. Modal-perfect: ‘The team may have solved the problem’—may thêm khả năng, have + solved nhìn sự việc như đã xảy ra trước mốc hiện tại.', ARRAY['clause', 'auxiliary', 'tense', 'aspect', 'modality']::text[], ARRAY['core-en-module-03', 'core-en-module-04', 'core-en-module-07']::text[], ARRAY['claude-owner-paste:english-2026-08-25', 'english-core-sources:v1', 'core-synthesis:english-generative-core-v1', 'english-core-transfer-answers-v1']::text[], 'published', 'codex', 'hiep'),
  ('core-en-75', 'core-en-module-10', 'mechanism', 'Vòng nghe–đoán–kiểm–nói lại biến input thành kiến thức sản xuất như thế nào?', 'Người học dự đoán structure/meaning, nghe để kiểm evidence, xem transcript/feedback sau nỗ lực, chẩn đoán gap, rồi tự tạo utterance cùng cơ chế trong context mới.', 'Vòng này nối retrieval, perception và transfer; chỉ tiêu thụ input không tự bảo đảm khả năng tự nói.', 'Hiểu được video nghĩa là các cấu trúc trong đó tự động chuyển sang active vocabulary.', 'Chọn một câu input thật và ghi rõ giả thuyết ban đầu, lỗi, bằng chứng sửa và câu transfer.', 'Input ‘I should have called earlier.’ Giả thuyết: người nói đánh giá một việc đã không làm. Lỗi ban đầu: nghe have thành of. Bằng chứng: modal + have + participle. Transfer: ‘I should have sent the message yesterday.’', ARRAY['phoneme', 'prosody', 'clause', 'collocation']::text[], ARRAY['core-en-module-08', 'core-en-module-09', 'core-en-module-10']::text[], ARRAY['claude-owner-paste:english-2026-08-25', 'english-core-sources:v1', 'core-synthesis:english-generative-core-v1', 'english-core-transfer-answers-v1']::text[], 'published', 'codex', 'hiep'),
  ('core-en-76', 'core-en-module-10', 'contrast', 'Phân biệt ‘đúng ngữ pháp’ với ‘phù hợp giao tiếp’ bằng một lời yêu cầu.', '‘Give me the report’ có thể đúng cấu trúc nhưng mức trực tiếp có thể không hợp quan hệ/ngữ cảnh; ‘Could you send me the report?’ đóng gói stance khác. Appropriateness phụ thuộc người nghe, mục tiêu, register và văn hóa cụ thể.', 'Generative grammar tạo lựa chọn; discourse/pragmatics giúp chọn lựa phù hợp, không có một câu lịch sự tuyệt đối.', 'Câu càng dài và dùng could càng luôn lịch sự hơn.', 'Tạo cùng yêu cầu cho bạn thân và cho khách hàng, giải thích form nào đổi và vì sao.', 'Bạn thân: ‘Send me the photos when you can.’ Khách hàng: ‘Could you send me the signed document when convenient?’ Câu thứ hai thêm modal, please/when convenient và noun phrase rõ để điều chỉnh directness/register, không chỉ sửa grammar.', ARRAY['discourse', 'modality', 'clause']::text[], ARRAY['core-en-module-04', 'core-en-module-07', 'core-en-module-10']::text[], ARRAY['claude-owner-paste:english-2026-08-25', 'english-core-sources:v1', 'core-synthesis:english-generative-core-v1', 'english-core-transfer-answers-v1']::text[], 'published', 'codex', 'hiep'),
  ('core-en-77', 'core-en-module-10', 'boundary', 'English Generative Core không thể thay thế những loại học nào, dù đã nắm chắc 80 thẻ?', 'Nó không thay input đa dạng, pronunciation feedback, lexical convention, genre/register, interaction, văn hóa hay trải nghiệm giao tiếp. Core là khung để gắn và suy kiến thức mới, không phải toàn bộ ngôn ngữ.', 'Nêu ranh giới ngăn ‘học từ gốc’ biến thành trì hoãn tiếp xúc thật hoặc niềm tin rằng mọi usage đều suy được.', 'Hiểu nguyên lý rồi thì không cần ghi nhớ chunks, ngoại lệ hoặc luyện với người thật.', 'Chọn một gap chỉ input/feedback thật mới sửa được và thiết kế cách thu bằng chứng trong tuần.', 'Gap: không biết prominence của mình có giúp người nghe nhận focus. Trong tuần, thu hai cách đọc cùng một câu, nhờ một người nghe nói họ hiểu phần nào được nhấn, rồi sửa và thu lại. Core một mình không tạo feedback này.', ARRAY['discourse', 'prosody', 'collocation', 'phoneme']::text[], ARRAY['core-en-module-10']::text[], ARRAY['claude-owner-paste:english-2026-08-25', 'english-core-sources:v1', 'core-synthesis:english-generative-core-v1', 'english-core-transfer-answers-v1']::text[], 'published', 'codex', 'hiep'),
  ('core-en-78', 'core-en-module-10', 'application', 'Gặp câu lạ ‘The proposal might have been rejected’, bạn phân tích từ gốc thế nào trước khi tra dịch?', 'Tìm clause roles: proposal là subject/patient; might là modality; have + participle là perfect; be + participle là passive; rejected mang event meaning. Sau đó dùng context để chốt thời điểm và độ chắc chắn.', 'Phân lớp cấu trúc thu hẹp meaning và chỉ rõ phần nào còn cần context/vocabulary.', 'Phân tích grammar cho phép biết chắc toàn bộ ý định người nói mà không cần discourse.', 'Thay rejected bằng một verb mới rồi đổi câu sang active, giữ mức độ chắc chắn tương đương.', 'Thay verb: ‘The proposal might have been delayed.’ Active với cùng độ chắc chắn: ‘The committee might have delayed the proposal.’ Might vẫn giữ modality; have delayed giữ perfect; committee được thêm làm agent subject.', ARRAY['clause', 'subject', 'object', 'auxiliary', 'tense', 'aspect', 'modality']::text[], ARRAY['core-en-module-04', 'core-en-module-06', 'core-en-module-07']::text[], ARRAY['claude-owner-paste:english-2026-08-25', 'english-core-sources:v1', 'core-synthesis:english-generative-core-v1', 'english-core-transfer-answers-v1']::text[], 'published', 'codex', 'hiep'),
  ('core-en-79', 'core-en-module-10', 'production', 'Tự nói 45 giây về một việc đã xảy ra và kế hoạch tiếp theo; tiêu chí tự kiểm nào phản ánh hiểu biết hơn đếm lỗi đơn lẻ?', 'Kiểm clause có roles rõ, tense/aspect/modality khớp timeline, reference theo dõi được, chunks đủ tự nhiên, prominence giúp focus, và người nghe hiểu mục tiêu; ghi một lỗi ưu tiên để sửa rồi nói lại.', 'Production có tiêu chí tầng giúp phản hồi hữu hạn và lặp có mục đích, không đòi hoàn hảo ngay lần đầu.', 'Chỉ số tốt nhất là nói không dừng và không có bất kỳ lỗi ngữ pháp nào.', 'Nói lại cùng nội dung cho một người nghe khác và điều chỉnh reference/register/focus.', 'Kể cho bạn thân có thể dùng reference chung và register thân mật; kể cho đồng nghiệp mới cần gọi tên người/vật rõ hơn, giải thích background và dùng từ trung tính hơn. Timeline cốt lõi giữ nguyên nhưng reference, register và focus đổi theo người nghe.', ARRAY['clause', 'tense', 'aspect', 'modality', 'reference', 'collocation', 'prosody']::text[], ARRAY['core-en-module-07', 'core-en-module-08', 'core-en-module-09', 'core-en-module-10']::text[], ARRAY['claude-owner-paste:english-2026-08-25', 'english-core-sources:v1', 'core-synthesis:english-generative-core-v1', 'english-core-transfer-answers-v1']::text[], 'published', 'codex', 'hiep'),
  ('core-en-80', 'core-en-module-10', 'production', 'Hãy dạy lại một nguyên lý trong bộ này và chỉ ra ít nhất ba nhánh kiến thức sinh từ nó cùng một ranh giới.', 'Đáp án đạt yêu cầu phát biểu principle bằng lời riêng, nối cơ chế tới ba ứng dụng/nhánh, đưa ví dụ mới, rồi nêu trường hợp cần convention, context hoặc nguồn khác thay vì suy máy móc.', 'Teach-back tích hợp recall, mechanism, transfer và epistemic boundary—đúng mục tiêu học một hiểu nhiều.', 'Kể lại càng nhiều thuật ngữ trong thẻ càng chứng minh hiểu sâu.', 'Dùng nguyên lý vừa dạy để phân tích một câu/input bạn chưa từng thấy trong bộ thẻ.', 'Ví dụ dùng nguyên lý finite carrier với câu lạ ‘The report could have been changed.’ Could là finite modal; have + been tạo perfect; been + changed tạo passive; report là subject/patient. Ranh giới: context vẫn cần để biết ai đổi và mức khả năng cụ thể.', ARRAY['clause', 'discourse', 'collocation', 'prosody']::text[], ARRAY['core-en-module-10']::text[], ARRAY['claude-owner-paste:english-2026-08-25', 'english-core-sources:v1', 'core-synthesis:english-generative-core-v1', 'english-core-transfer-answers-v1']::text[], 'published', 'codex', 'hiep')
